window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6d4455723fadd3b4"]={"versions": [{"id": "FIG-6d4455723fadd3b4", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (M2-Metamodellausschnitt der AUTOSAR Template-Spezifikation <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition diagnostischer Service-Bedarfe (<code>ServiceNeeds</code>) von Software-Komponenten (SW-C) mit Schwerpunkt auf emissionsrelevanter On-Board-Diagnose (OBD-II nach SAE J1979 / ISO 15031, WWH-OBD nach ISO 27145) und Funktionsdeaktivierung (FIM).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient Generatoren (RTE- und BSW-Generatoren) als vertragliche Spezifikationsgrundlage zur automatischen Ableitung von RTE-Service-Ports (Client-Server / Sender-Receiver) sowie BSW-Modulkonfigurationen für <code>Dem</code> (Diagnostic Event Manager), <code>Dcm</code> (Diagnostic Communication Manager) und <code>FiM</code> (Function Inhibition Manager).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basisklassen & Metamodell-Verankerung</p>\n<ul class=\"fig-list\">\n<li><strong><code>ServiceMapping::SwcServiceDependency</code></strong> (Spezialisierung von <code>ServiceDependency</code>, <code>Identifiable</code>, <code>AtpStructureElement</code>):</li>\n<li>Aggregiert kompositorisch über <code>+serviceNeeds</code> exakt eine Instanz (<code>1</code>) von <code>ServiceNeeds</code>. Verknüpft die Bedarfe mit konkreten SW-C-Ports oder internem Verhalten.</li>\n<li><strong><code>ServiceNeeds</code></strong> (abstrakt, <code>Identifiable</code>):</li>\n<li>Basisklasse für alle von einer SW-C deklarierten BSW-Dienstbedarfe.</li>\n<li><strong><code>DiagnosticCapabilityElement</code></strong> (abstrakt, erbt von <code>ServiceNeeds</code>):</li>\n<li>Gemeinsame Basis für diagnosebezogene Service-Bedarfe.</li>\n<li><em>Attribute:</em></li>\n<li><code>audience: DiagnosticAudienceEnum [0..*]</code> – Zielgruppe/Freigabekreis (z. B. Aftersales, Manufacturing).</li>\n<li><code>diagRequirement: DiagRequirementIdString [0..1]</code> – Rückverfolgbarkeits-ID zu gesetzlichen/funktionalen Anforderungen.</li>\n<li><code>securityAccessLevel: PositiveInteger [0..1]</code> – Erforderliche Sicherheitsstufe (Seed & Key gemäß UDS/OBD).</li>\n</ul>\n<p class=\"fig-p\">#### Diagnostische Ereignisse & Funktionsinhibition</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticEventNeeds</code></strong> (erbt von <code>DiagnosticCapabilityElement</code>):</li>\n<li>Deklariert ein Diagnoseereignis (Debouncing, DTC-Statusverarbeitung im <code>Dem</code>).</li>\n<li><em>Attribute:</em></li>\n<li><code>considerPtoStatus: Boolean</code> – Berücksichtigung des Power Take-Off (Nebenantriebs-)Status für Fehlererkennung/MIL.</li>\n<li><code>dtcKind: DtcKindEnum</code> – Klassifikation über Enumeration (<code>emissionRelatedDtc</code>, <code>nonEmmissionRelatedDtc</code>).</li>\n<li><code>dtcNumber: PositiveInteger [0..1]</code> – Spezifische DTC-Nummer (OBD/UDS).</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+inhibitingFid</code> (<code>0..1</code>) zu <code>FunctionInhibitionNeeds</code>: Primärer Funktionsbezeichner (FID), der dieses Event bei aktivem Fehler inhibiert.</li>\n<li><code>+inhibitingSecondaryFid</code> (<code>0..*</code>) zu <code>FunctionInhibitionNeeds</code>: Sekundäre FIDs zur Kaskadierung von Inhibitionsbedingungen.</li>\n<li><strong><code>FunctionInhibitionNeeds</code></strong> (erbt direkt von <code>ServiceNeeds</code>):</li>\n<li>Repräsentiert die logische Entkopplung von Fehlererkennung und Fehlerreaktion über Function Identifiers (FIDs) im <code>FiM</code>.</li>\n</ul>\n<p class=\"fig-p\">#### OBD-spezifische Service-Bedarfe (Spezialisierungen von <code>DiagnosticCapabilityElement</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ObdRatioServiceNeeds</code></strong>:</li>\n<li>Konfiguriert das In-Use Monitor Performance Ratio (IUMPR) Tracking gemäß CARB/EPA-Gesetzgebung.</li>\n<li><em>Attribute:</em></li>\n<li><code>connectionType: ObdRatioConnectionKindEnum</code> – Steuerungsart (<code>apiUse</code> vs. <code>observer</code>).</li>\n<li><code>iumprGroup: NameToken</code> – Gruppenzugehörigkeit des Monitors zur IUMPR-Clusterung.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+rateBasedMonitoredEvent</code> (<code>1</code>): Referenziert exakt ein übergeordnetes <code>DiagnosticEventNeeds</code>.</li>\n<li><code>+usedFid</code> (<code>0..1</code>) und <code>+usedSecondaryFid</code> (<code>0..*</code>): Referenziert <code>FunctionInhibitionNeeds</code>, deren Zustand das Inkrementieren des Denominators blockiert/freigibt.</li>\n<li><strong><code>ObdPidServiceNeeds</code></strong>:</li>\n<li>Repräsentiert OBD Parameter IDs (Service $01 / $02 / $09).</li>\n<li><em>Attribute:</em> <code>dataLength: PositiveInteger [0..1]</code>, <code>parameterId: PositiveInteger</code> (PID-Wert), <code>standard: String</code>.</li>\n<li><strong><code>ObdInfoServiceNeeds</code></strong>:</li>\n<li>Deklariert Fahrzeug- und Systeminformationen (Service $09 InfoTypes, z. B. VIN, CVN, CALID).</li>\n<li><em>Attribute:</em> <code>dataLength: PositiveInteger [0..1]</code>, <code>infoType: PositiveInteger</code>.</li>\n<li><strong><code>ObdMonitorServiceNeeds</code></strong>:</li>\n<li>Unterstützt On-Board-Monitor-Testergebnisse für nicht kontinuierlich überwachte Systeme (OBD Service $06 / Mode $06).</li>\n<li><em>Attribute:</em> <code>onBoardMonitorId: PositiveInteger</code> (OBDMID), <code>testId: PositiveInteger</code> (TID), <code>unitAndScalingId: PositiveInteger</code> (UASID).</li>\n<li><strong><code>ObdControlServiceNeeds</code></strong>:</li>\n<li>Ermöglicht bidirektionale Steuerung von On-Board-Komponenten/Tests via OBD Service $08.</li>\n<li><em>Attribute:</em> <code>testId: PositiveInteger</code> (TID).</li>\n</ul>\n<p class=\"fig-p\">#### Enumerationen</p>\n<ul class=\"fig-list\">\n<li><strong><code>DtcKindEnum</code></strong>: <code>emissionRelatedDtc</code>, <code>nonEmmissionRelatedDtc</code>.</li>\n<li><strong><code>ObdRatioConnectionKindEnum</code></strong>:</li>\n<li><code>apiUse</code>: SW-C triggert Zählerstände aktiv über dedizierte BSW-APIs.</li>\n<li><code>observer</code>: BSW (<code>Dem</code>) überwacht das Fehlerereignis und die FIDs autonom zur Ratio-Aktualisierung.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell bildet statische Verträge ab, bestimmt jedoch folgende Laufzeitinteraktionen zwischen Applikation (<code>SW-C</code>), RTE und BSW-Modulen:</p>\n<ol class=\"fig-list\">\n<li><strong>Ereignis- & Fehlermeldung (<code>DiagnosticEventNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die SW-C setzt Diagnosestati asynchron via RTE über die Schnittstelle <code>DiagnosticMonitor</code> (<code>SetEventStatus</code>).</li>\n<li>Das <code>Dem</code> verarbeitet Entprellung und Statusbits (z. B. <code>TEST_FAILED</code>). Ist <code>dtcKind == emissionRelatedDtc</code>, werden MIL-Zähler, Freeze-Frame-Speicherung (Mode $02) und Fault-Memory-Abläufe forciert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Funktionsinhibition (<code>FunctionInhibitionNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schlägt ein Event fehl, aktiviert der <code>Dem</code> den hinterlegten Inhibitionszustand im <code>FiM</code>.</li>\n<li>Betroffene Komponenten prüfen vor Ausführung funktionsrelevanter Routinen über RTE (<code>FunctionInhibition</code>-Port) synchron via <code>GetFunctionPermission(FID, &amp;Permission)</code> die Freigabe.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>IUMPR-Berechnung (<code>ObdRatioServiceNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Modus <code>observer</code>:</strong> Das <code>Dem</code> detektiert Betriebsbedingungen selbstständig. Sobald die durch <code>usedFid</code> referenzierten FIDs fehlerfrei sind, wird der Denominator inkrementiert; schließt der Monitor über <code>DiagnosticEventNeeds</code> erfolgreich ab, wird der Numerator inkrementiert.</li>\n<li><strong>Modus <code>apiUse</code>:</strong> Die SW-C steuert Denominator- und Numerator-Fortschritt explizit durch Aufruf der RTE-APIs (z. B. <code>Dem_RepIUMPRDenLock</code>, <code>Dem_SetIUMPRDenCondition</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>OBD-Dienstabfrage (Services $01, $06, $08, $09):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein externer Tester fordert PIDs/TIDs über CAN/Ethernet an.</li>\n<li><code>Dcm</code> empfängt die Anfrage und ruft synchron oder asynchron die generierten Service-Ports der SW-C auf (z. B. <code>DataServices_OBD_*</code> für PID-Werte oder <code>CallbackDCMRequestControl</code> für Mode $08).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE- & BSW-Konfigurationskonsistenz (TPS_SWCT_1046):</strong></li>\n<li>Deklariert eine SW-C ein <code>ObdRatioServiceNeeds</code>, muss zwingend die Assoziation <code>+rateBasedMonitoredEvent</code> auf ein valides <code>DiagnosticEventNeeds</code> gesetzt sein.</li>\n<li>Fehlt die Zuordnung oder verweist sie auf ein nicht emissionsrelevantes Event (<code>dtcKind != emissionRelatedDtc</code>), verletzen Systemgeneratoren die Konfigurationsvalidierung für OBD-Konformität.</li>\n<li><strong>Vermeidung von Priority Inversion / Deadlocks bei FIDs:</strong></li>\n<li>Die Kopplung von <code>usedFid</code> an <code>ObdRatioServiceNeeds</code> verhindert das unzulässige Inkrementieren des IUMPR-Denominators, wenn vorgelagerte Diagnosen (z. B. Sensor-Plausibilität) die Durchführung des Monitors verhindern. Applikationsentwickler müssen FIDs so modellieren, dass zirkuläre Abhängigkeiten zwischen <code>inhibitingFid</code> und <code>usedFid</code> ausgeschlossen sind.</li>\n<li><strong>Port-Schnittstellenverträge:</strong></li>\n<li>Die Deklaration von <code>ObdPidServiceNeeds</code> bzw. <code>ObdInfoServiceNeeds</code> erzeugt zwingend typisierte Client-Server-Ports an der SW-C. Entwickler müssen sicherstellen, dass die Rückgabe-Payloads exakt der modellierten <code>dataLength</code> entsprechen, um PDU-Pufferüberläufe im <code>Dcm</code> zu verhindern.</li>\n</ul>"}, {"id": "FIG-7b99c529e35c0d0d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (M2-Metamodellausschnitt der AUTOSAR Template-Spezifikation <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition diagnostischer Service-Bedarfe (<code>ServiceNeeds</code>) von Software-Komponenten (SW-C) mit Schwerpunkt auf emissionsrelevanter On-Board-Diagnose (OBD-II nach SAE J1979 / ISO 15031, WWH-OBD nach ISO 27145) und Funktionsdeaktivierung (FIM).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient Generatoren (RTE- und BSW-Generatoren) als vertragliche Spezifikationsgrundlage zur automatischen Ableitung von RTE-Service-Ports (Client-Server / Sender-Receiver) sowie BSW-Modulkonfigurationen für <code>Dem</code> (Diagnostic Event Manager), <code>Dcm</code> (Diagnostic Communication Manager) und <code>FiM</code> (Function Inhibition Manager).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basisklassen & Metamodell-Verankerung</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwcServiceDependency</code></strong> (Spezialisierung von <code>ServiceDependency</code>, <code>Identifiable</code>, <code>AtpStructureElement</code>):</li>\n<li>Aggregiert kompositorisch über <code>+serviceNeeds</code> exakt eine Instanz (<code>1</code>) von <code>ServiceNeeds</code>. Verknüpft die Bedarfe mit konkreten SW-C-Ports oder internem Verhalten.</li>\n<li><strong><code>ServiceNeeds</code></strong> (abstrakt, <code>Identifiable</code>):</li>\n<li>Basisklasse für alle von einer SW-C deklarierten BSW-Dienstbedarfe.</li>\n<li><strong><code>DiagnosticCapabilityElement</code></strong> (abstrakt, erbt von <code>ServiceNeeds</code>):</li>\n<li>Gemeinsame Basis für diagnosebezogene Service-Bedarfe.</li>\n<li><em>Attribute:</em></li>\n<li><code>audience: DiagnosticAudienceEnum [0..*]</code> – Zielgruppe/Freigabekreis (z. B. Aftersales, Manufacturing).</li>\n<li><code>diagRequirement: DiagRequirementIdString [0..1]</code> – Rückverfolgbarkeits-ID zu gesetzlichen/funktionalen Anforderungen.</li>\n<li><code>securityAccessLevel: PositiveInteger [0..1]</code> – Erforderliche Sicherheitsstufe (Seed & Key gemäß UDS/OBD).</li>\n</ul>\n<p class=\"fig-p\">#### Diagnostische Ereignisse & Funktionsinhibition</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticEventNeeds</code></strong> (erbt von <code>DiagnosticCapabilityElement</code>):</li>\n<li>Deklariert ein Diagnoseereignis (Debouncing, DTC-Statusverarbeitung im <code>Dem</code>).</li>\n<li><em>Attribute:</em></li>\n<li><code>considerPtoStatus: Boolean [0..1]</code> – Berücksichtigung des Power Take-Off (Nebenantriebs-)Status für Fehlererkennung/MIL.</li>\n<li><code>dtcKind: DtcKindEnum [0..1]</code> – Klassifikation über Enumeration (<code>emissionRelatedDtc</code>, <code>nonEmmissionRelatedDtc</code>).</li>\n<li><code>dtcNumber: PositiveInteger [0..1]</code> – Spezifische DTC-Nummer.</li>\n<li><code>obdDtcNumber: PositiveInteger [0..1]</code> – Spezifische OBD-DTC-Nummer.</li>\n<li><code>udsDtcNumber: PositiveInteger [0..1]</code> – Spezifische UDS-DTC-Nummer.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+inhibitingFid</code> (<code>0..1</code>) zu <code>FunctionInhibitionNeeds</code>: Primärer Funktionsbezeichner (FID), der dieses Event bei aktivem Fehler inhibiert.</li>\n<li><code>+inhibitingSecondaryFid</code> (<code>0..*</code>) zu <code>FunctionInhibitionNeeds</code>: Sekundäre FIDs zur Kaskadierung von Inhibitionsbedingungen.</li>\n<li><strong><code>FunctionInhibitionNeeds</code></strong> (erbt direkt von <code>ServiceNeeds</code>):</li>\n<li>Repräsentiert die logische Entkopplung von Fehlererkennung und Fehlerreaktion über Function Identifiers (FIDs) im <code>FiM</code>.</li>\n</ul>\n<p class=\"fig-p\">#### OBD-spezifische Service-Bedarfe (Spezialisierungen von <code>DiagnosticCapabilityElement</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ObdRatioServiceNeeds</code></strong>:</li>\n<li>Konfiguriert das In-Use Monitor Performance Ratio (IUMPR) Tracking gemäß CARB/EPA-Gesetzgebung.</li>\n<li><em>Attribute:</em></li>\n<li><code>connectionType: ObdRatioConnectionKindEnum</code> – Steuerungsart (<code>apiUse</code> vs. <code>observer</code>).</li>\n<li><code>iumprGroup: NameToken</code> – Gruppenzugehörigkeit des Monitors zur IUMPR-Clusterung.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+rateBasedMonitoredEvent</code> (<code>1</code>): Referenziert exakt ein übergeordnetes <code>DiagnosticEventNeeds</code>.</li>\n<li><code>+usedFid</code> (<code>0..1</code>) und <code>+usedSecondaryFid</code> (<code>0..*</code>): Referenziert <code>FunctionInhibitionNeeds</code>, deren Status für das Ratio relevant ist.</li>\n<li><strong><code>ObdPidServiceNeeds</code></strong>:</li>\n<li>Deklariert Bedarfe für Parameter Identifier (PID) Services nach OBD-II.</li>\n<li><em>Attribute:</em></li>\n<li><code>dataLength: PositiveInteger [0..1]</code> – Datenlänge des Parameters in Byte.</li>\n<li><code>parameterId: PositiveInteger</code> – Kennung des PIDs.</li>\n<li><code>standard: String</code> – Zugrundeliegender Standard (z. B. SAE J1979).</li>\n<li><strong><code>ObdInfoServiceNeeds</code></strong>:</li>\n<li>Spezifiziert Bedarfe bezüglich InfoType-Diensten (OBD Service $09).</li>\n<li><em>Attribute:</em></li>\n<li><code>dataLength: PositiveInteger [0..1]</code> – Datenlänge der InfoType-Nutzdaten.</li>\n<li><code>infoType: PositiveInteger</code> – Numerische InfoType-Kennung.</li>\n<li><strong><code>ObdMonitorServiceNeeds</code></strong>:</li>\n<li>Beschreibt Service-Bedarfe für On-Board-Monitore (OBD Service $06).</li>\n<li><em>Attribute:</em></li>\n<li><code>onBoardMonitorId: PositiveInteger</code> – Monitor-Identifier (OBDMID).</li>\n<li><code>testId: PositiveInteger</code> – Test-Identifier (TID).</li>\n<li><code>unitAndScalingId: PositiveInteger</code> – Skalierungs- und Einheitenbezeichner (UASID).</li>\n<li><strong><code>ObdControlServiceNeeds</code></strong>:</li>\n<li>Definiert Steuerungsanforderungen für Test-IDs im Rahmen von OBD.</li>\n<li><em>Attribute:</em></li>\n<li><code>testId: PositiveInteger</code> – Test-Identifier für Prüfablaufsteuerung.</li>\n</ul>\n<p class=\"fig-p\">#### Aufzählungstypen (Enumerations)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ObdRatioConnectionKindEnum</code></strong>: Definiert die Anbindungsart (<code>apiUse</code>, <code>observer</code>).</li>\n<li><strong><code>DtcKindEnum</code></strong>: Unterscheidet Diagnosefehlercodes (<code>emissionRelatedDtc</code>, <code>nonEmmissionRelatedDtc</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell bildet statische Verträge ab, bestimmt jedoch folgende Laufzeitinteraktionen zwischen Applikation (<code>SW-C</code>), RTE und BSW-Modulen:</p>\n<ol class=\"fig-list\">\n<li><strong>Ereignis- & Fehlermeldung (<code>DiagnosticEventNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die SW-C setzt Diagnosestati asynchron via RTE über die Schnittstelle <code>DiagnosticMonitor</code> (<code>SetEventStatus</code>).</li>\n<li>Das <code>Dem</code> verarbeitet Entprellung und Statusbits (z. B. <code>TEST_FAILED</code>). Ist <code>dtcKind == emissionRelatedDtc</code>, werden MIL-Zähler, Freeze-Frame-Speicherung (Mode $02) und Fault-Memory-Abläufe forciert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Funktionsinhibition (<code>FunctionInhibitionNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schlägt ein Event fehl, aktiviert der <code>Dem</code> den hinterlegten Inhibitionszustand im <code>FiM</code>.</li>\n<li>Betroffene Komponenten prüfen vor Ausführung funktionsrelevanter Routinen über RTE (<code>FunctionInhibition</code>-Port) synchron via <code>GetFunctionPermission(FID, &amp;Permission)</code> die Freigabe.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>IUMPR-Berechnung (<code>ObdRatioServiceNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Modus <code>observer</code>:</strong> Das <code>Dem</code> detektiert Betriebsbedingungen selbstständig. Sobald die durch <code>usedFid</code> referenzierten FIDs fehlerfrei sind, wird der Denominator inkrementiert; schließt der Monitor über <code>DiagnosticEventNeeds</code> erfolgreich ab, wird der Numerator inkrementiert.</li>\n<li><strong>Modus <code>apiUse</code>:</strong> Die SW-C steuert Denominator- und Numerator-Fortschritt explizit durch Aufruf der RTE-APIs (z. B. <code>Dem_RepIUMPRDenLock</code>, <code>Dem_SetIUMPRDenCondition</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>OBD-Dienstabfrage (Services $01, $06, $08, $09):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein externer Tester fordert PIDs/TIDs über CAN/Ethernet an.</li>\n<li><code>Dcm</code> empfängt die Anfrage und ruft synchron oder asynchron die generierten Service-Ports der SW-C auf (z. B. <code>DataServices_OBD_*</code> für PID-Werte oder <code>CallbackDCMRequestControl</code> für Mode $08).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE- & BSW-Konfigurationskonsistenz (TPS_SWCT_1046):</strong></li>\n<li>Deklariert eine SW-C ein <code>ObdRatioServiceNeeds</code>, muss zwingend die Assoziation <code>+rateBasedMonitoredEvent</code> auf ein valides <code>DiagnosticEventNeeds</code> gesetzt sein.</li>\n<li>Fehlt die Zuordnung oder verweist sie auf ein nicht emissionsrelevantes Event (<code>dtcKind != emissionRelatedDtc</code>), verletzen Systemgeneratoren die Konfigurationsvalidierung für OBD-Konformität.</li>\n<li><strong>Vermeidung von Priority Inversion / Deadlocks bei FIDs:</strong></li>\n<li>Die Kopplung von <code>usedFid</code> an <code>ObdRatioServiceNeeds</code> verhindert das unzulässige Inkrementieren des IUMPR-Denominators, wenn vorgelagerte Diagnosen (z. B. Sensor-Plausibilität) die Durchführung des Monitors verhindern. Applikationsentwickler müssen FIDs so modellieren, dass zirkuläre Abhängigkeiten zwischen <code>inhibitingFid</code> und <code>usedFid</code> ausgeschlossen sind.</li>\n<li><strong>Port-Schnittstellenverträge:</strong></li>\n<li>Die Deklaration von <code>ObdPidServiceNeeds</code> bzw. <code>ObdInfoServiceNeeds</code> erzeugt zwingend typisierte Client-Server-Ports an der SW-C. Entwickler müssen sicherstellen, dass die Rückgabe-Payloads exakt der modellierten <code>dataLength</code> entsprechen, um PDU-Pufferüberläufe im <code>Dcm</code> zu verhindern.</li>\n</ul>"}, {"id": "FIG-1e7e63823cc98073", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (M2-Metamodellausschnitt der AUTOSAR Template-Spezifikation <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition diagnostischer Service-Bedarfe (<code>ServiceNeeds</code>) von Software-Komponenten (SW-C) mit Schwerpunkt auf emissionsrelevanter On-Board-Diagnose (OBD-II nach SAE J1979 / ISO 15031, WWH-OBD nach ISO 27145) und Funktionsdeaktivierung (FIM).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient Generatoren (RTE- und BSW-Generatoren) als vertragliche Spezifikationsgrundlage zur automatischen Ableitung von RTE-Service-Ports (Client-Server / Sender-Receiver) sowie BSW-Modulkonfigurationen für <code>Dem</code> (Diagnostic Event Manager), <code>Dcm</code> (Diagnostic Communication Manager) und <code>FiM</code> (Function Inhibition Manager).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basisklassen & Metamodell-Verankerung</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwcServiceDependency</code></strong> (Spezialisierung von <code>ServiceDependency</code>, <code>Identifiable</code>, <code>AtpStructureElement</code>):</li>\n<li>Aggregiert kompositorisch über <code>+serviceNeeds</code> exakt eine Instanz (<code>1</code>) von <code>ServiceNeeds</code>. Verknüpft die Bedarfe mit konkreten SW-C-Ports oder internem Verhalten.</li>\n<li><strong><code>ServiceNeeds</code></strong> (abstrakt, <code>Identifiable</code>):</li>\n<li>Basisklasse für alle von einer SW-C deklarierten BSW-Dienstbedarfe.</li>\n<li><strong><code>DiagnosticCapabilityElement</code></strong> (abstrakt, erbt von <code>ServiceNeeds</code>):</li>\n<li>Gemeinsame Basis für diagnosebezogene Service-Bedarfe.</li>\n<li><em>Attribute:</em></li>\n<li><code>audience: DiagnosticAudienceEnum [0..*]</code> – Zielgruppe/Freigabekreis (z. B. Aftersales, Manufacturing).</li>\n<li><code>diagRequirement: DiagRequirementIdString [0..1]</code> – Rückverfolgbarkeits-ID zu gesetzlichen/funktionalen Anforderungen.</li>\n<li><code>securityAccessLevel: PositiveInteger [0..1]</code> – Erforderliche Sicherheitsstufe (Seed & Key gemäß UDS/OBD).</li>\n</ul>\n<p class=\"fig-p\">#### Diagnostische Ereignisse & Funktionsinhibition</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticEventNeeds</code></strong> (erbt von <code>DiagnosticCapabilityElement</code>):</li>\n<li>Deklariert ein Diagnoseereignis (Debouncing, DTC-Statusverarbeitung im <code>Dem</code>).</li>\n<li><em>Attribute:</em></li>\n<li><code>considerPtoStatus: Boolean [0..1]</code> – Berücksichtigung des Power Take-Off (Nebenantriebs-)Status für Fehlererkennung/MIL.</li>\n<li><code>dtcKind: DtcKindEnum [0..1]</code> – Klassifikation über Enumeration (<code>emissionRelatedDtc</code>, <code>nonEmmissionRelatedDtc</code>).</li>\n<li><code>obdDtcNumber: PositiveInteger [0..1]</code> – Spezifische OBD-DTC-Nummer.</li>\n<li><code>reportBehavior: ReportBehaviorEnum [0..1]</code> – Meldeverhalten des Diagnoseereignisses.</li>\n<li><code>udsDtcNumber: PositiveInteger [0..1]</code> – Spezifische UDS-DTC-Nummer.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+inhibitingFid</code> (<code>0..1</code>) zu <code>FunctionInhibitionNeeds</code>: Primärer Funktionsbezeichner (FID), der dieses Event bei aktivem Fehler inhibiert.</li>\n<li><code>+inhibitingSecondaryFid</code> (<code>0..*</code>) zu <code>FunctionInhibitionNeeds</code>: Sekundäre FIDs zur Kaskadierung von Inhibitionsbedingungen.</li>\n<li><code>+deferringFid</code> (<code>0..*</code>) zu <code>FunctionInhibitionNeeds</code>: FIDs zur Verzögerung der Fehlerreaktion/Fehlerspeicherung.</li>\n<li><strong><code>FunctionInhibitionNeeds</code></strong> (erbt direkt von <code>ServiceNeeds</code>):</li>\n<li>Repräsentiert die logische Entkopplung von Fehlererkennung und Fehlerreaktion über Function Identifiers (FIDs) im <code>FiM</code>.</li>\n</ul>\n<p class=\"fig-p\">#### OBD-spezifische Service-Bedarfe (Spezialisierungen von <code>DiagnosticCapabilityElement</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ObdRatioServiceNeeds</code></strong>:</li>\n<li>Konfiguriert das In-Use Monitor Performance Ratio (IUMPR) Tracking gemäß CARB/EPA-Gesetzgebung.</li>\n<li><em>Attribute:</em></li>\n<li><code>connectionType: ObdRatioConnectionKindEnum</code> – Steuerungsart (<code>apiUse</code> vs. <code>observer</code>).</li>\n<li><code>iumprGroup: NameToken</code> – Gruppenzugehörigkeit des Monitors zur IUMPR-Clusterung.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+rateBasedMonitoredEvent</code> (<code>1</code>): Referenziert exakt ein übergeordnetes <code>DiagnosticEventNeeds</code>.</li>\n<li><code>+usedFid</code> (<code>0..1</code>) und <code>+usedSecondaryFid</code> (<code>0..*</code>): Referenziert <code>FunctionInhibitionNeeds</code>, deren Status für das Ratio relevant ist.</li>\n<li><strong><code>ObdPidServiceNeeds</code></strong>:</li>\n<li>Deklariert Bedarfe für Parameter Identifier (PID) Services nach OBD-II.</li>\n<li><em>Attribute:</em></li>\n<li><code>dataLength: PositiveInteger [0..1]</code> – Datenlänge des Parameters in Byte.</li>\n<li><code>parameterId: PositiveInteger</code> – Kennung des PIDs.</li>\n<li><code>standard: String</code> – Zugrundeliegender Standard (z. B. SAE J1979).</li>\n<li><strong><code>ObdInfoServiceNeeds</code></strong>:</li>\n<li>Spezifiziert Bedarfe bezüglich InfoType-Diensten (OBD Service $09).</li>\n<li><em>Attribute:</em></li>\n<li><code>dataLength: PositiveInteger [0..1]</code> – Datenlänge der InfoType-Nutzdaten.</li>\n<li><code>infoType: PositiveInteger</code> – Numerische InfoType-Kennung.</li>\n<li><strong><code>ObdMonitorServiceNeeds</code></strong>:</li>\n<li>Beschreibt Service-Bedarfe für On-Board-Monitore (OBD Service $06).</li>\n<li><em>Attribute:</em></li>\n<li><code>onBoardMonitorId: PositiveInteger</code> – Monitor-Identifier (OBDMID).</li>\n<li><code>testId: PositiveInteger</code> – Test-Identifier (TID).</li>\n<li><code>unitAndScalingId: PositiveInteger</code> – Skalierungs- und Einheitenbezeichner (UASID).</li>\n<li><strong><code>ObdControlServiceNeeds</code></strong>:</li>\n<li>Definiert Steuerungsanforderungen für Test-IDs im Rahmen von OBD.</li>\n<li><em>Attribute:</em></li>\n<li><code>testId: PositiveInteger</code> – Test-Identifier für Prüfablaufsteuerung.</li>\n</ul>\n<p class=\"fig-p\">#### Aufzählungstypen (Enumerations)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ObdRatioConnectionKindEnum</code></strong>: Definiert die Anbindungsart (<code>apiUse</code>, <code>observer</code>).</li>\n<li><strong><code>DtcKindEnum</code></strong>: Unterscheidet Diagnosefehlercodes (<code>emissionRelatedDtc</code>, <code>nonEmmissionRelatedDtc</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell bildet statische Verträge ab, bestimmt jedoch folgende Laufzeitinteraktionen zwischen Applikation (<code>SW-C</code>), RTE und BSW-Modulen:</p>\n<ol class=\"fig-list\">\n<li><strong>Ereignis- & Fehlermeldung (<code>DiagnosticEventNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die SW-C setzt Diagnosestati asynchron via RTE über die Schnittstelle <code>DiagnosticMonitor</code> (<code>SetEventStatus</code>).</li>\n<li>Das <code>Dem</code> verarbeitet Entprellung und Statusbits (z. B. <code>TEST_FAILED</code>). Ist <code>dtcKind == emissionRelatedDtc</code>, werden MIL-Zähler, Freeze-Frame-Speicherung (Mode $02) und Fault-Memory-Abläufe forciert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Funktionsinhibition (<code>FunctionInhibitionNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schlägt ein Event fehl, aktiviert der <code>Dem</code> den hinterlegten Inhibitionszustand im <code>FiM</code>.</li>\n<li>Betroffene Komponenten prüfen vor Ausführung funktionsrelevanter Routinen über RTE (<code>FunctionInhibition</code>-Port) synchron via <code>GetFunctionPermission(FID, &amp;Permission)</code> die Freigabe.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>IUMPR-Berechnung (<code>ObdRatioServiceNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Modus <code>observer</code>:</strong> Das <code>Dem</code> detektiert Betriebsbedingungen selbstständig. Sobald die durch <code>usedFid</code> referenzierten FIDs fehlerfrei sind, wird der Denominator inkrementiert; schließt der Monitor über <code>DiagnosticEventNeeds</code> erfolgreich ab, wird der Numerator inkrementiert.</li>\n<li><strong>Modus <code>apiUse</code>:</strong> Die SW-C steuert Denominator- und Numerator-Fortschritt explizit durch Aufruf der RTE-APIs (z. B. <code>Dem_RepIUMPRDenLock</code>, <code>Dem_SetIUMPRDenCondition</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>OBD-Dienstabfrage (Services $01, $06, $08, $09):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein externer Tester fordert PIDs/TIDs über CAN/Ethernet an.</li>\n<li><code>Dcm</code> empfängt die Anfrage und ruft synchron oder asynchron die generierten Service-Ports der SW-C auf (z. B. <code>DataServices_OBD_*</code> für PID-Werte oder <code>CallbackDCMRequestControl</code> für Mode $08).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE- & BSW-Konfigurationskonsistenz (TPS_SWCT_1046):</strong></li>\n<li>Deklariert eine SW-C ein <code>ObdRatioServiceNeeds</code>, muss zwingend die Assoziation <code>+rateBasedMonitoredEvent</code> auf ein valides <code>DiagnosticEventNeeds</code> gesetzt sein.</li>\n<li>Fehlt die Zuordnung oder verweist sie auf ein nicht emissionsrelevantes Event (<code>dtcKind != emissionRelatedDtc</code>), verletzen Systemgeneratoren die Konfigurationsvalidierung für OBD-Konformität.</li>\n<li><strong>Vermeidung von Priority Inversion / Deadlocks bei FIDs:</strong></li>\n<li>Die Kopplung von <code>usedFid</code> an <code>ObdRatioServiceNeeds</code> verhindert das unzulässige Inkrementieren des IUMPR-Denominators, wenn vorgelagerte Diagnosen (z. B. Sensor-Plausibilität) die Durchführung des Monitors verhindern. Applikationsentwickler müssen FIDs so modellieren, dass zirkuläre Abhängigkeiten zwischen <code>inhibitingFid</code> und <code>usedFid</code> ausgeschlossen sind.</li>\n<li><strong>Port-Schnittstellenverträge:</strong></li>\n<li>Die Deklaration von <code>ObdPidServiceNeeds</code> bzw. <code>ObdInfoServiceNeeds</code> erzeugt zwingend typisierte Client-Server-Ports an der SW-C. Entwickler müssen sicherstellen, dass die Rückgabe-Payloads exakt der modellierten <code>dataLength</code> entsprechen, um PDU-Pufferüberläufe im <code>Dcm</code> zu verhindern.</li>\n</ul>"}, {"id": "FIG-cc9257a44469d4b5", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (M2-Metamodellausschnitt der AUTOSAR Template-Spezifikation <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition diagnostischer Service-Bedarfe (<code>ServiceNeeds</code>) von Software-Komponenten (SW-C) mit Schwerpunkt auf emissionsrelevanter On-Board-Diagnose (OBD-II nach SAE J1979 / ISO 15031, WWH-OBD nach ISO 27145) und Funktionsdeaktivierung (FIM).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient Generatoren (RTE- und BSW-Generatoren) als vertragliche Spezifikationsgrundlage zur automatischen Ableitung von RTE-Service-Ports (Client-Server / Sender-Receiver) sowie BSW-Modulkonfigurationen für <code>Dem</code> (Diagnostic Event Manager), <code>Dcm</code> (Diagnostic Communication Manager) und <code>FiM</code> (Function Inhibition Manager).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basisklassen & Metamodell-Verankerung</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwcServiceDependency</code></strong> (Spezialisierung von <code>ServiceDependency</code>, <code>Identifiable</code>, <code>AtpStructureElement</code>):</li>\n<li>Aggregiert kompositorisch über <code>+serviceNeeds</code> exakt eine Instanz (<code>1</code>) von <code>ServiceNeeds</code>. Verknüpft die Bedarfe mit konkreten SW-C-Ports oder internem Verhalten.</li>\n<li><strong><code>ServiceNeeds</code></strong> (abstrakt, <code>Identifiable</code>):</li>\n<li>Basisklasse für alle von einer SW-C deklarierten BSW-Dienstbedarfe.</li>\n<li><strong><code>DiagnosticCapabilityElement</code></strong> (abstrakt, erbt von <code>ServiceNeeds</code>):</li>\n<li>Gemeinsame Basis für diagnosebezogene Service-Bedarfe.</li>\n<li><em>Attribute:</em></li>\n<li><code>audience: DiagnosticAudienceEnum [0..*]</code> – Zielgruppe/Freigabekreis (z. B. Aftersales, Manufacturing).</li>\n<li><code>diagRequirement: DiagRequirementIdString [0..1]</code> – Rückverfolgbarkeits-ID zu gesetzlichen/funktionalen Anforderungen.</li>\n<li><code>securityAccessLevel: PositiveInteger [0..1]</code> – Erforderliche Sicherheitsstufe (Seed & Key gemäß UDS/OBD).</li>\n</ul>\n<p class=\"fig-p\">#### Diagnostische Ereignisse & Funktionsinhibition</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticEventNeeds</code></strong> (erbt von <code>DiagnosticCapabilityElement</code>):</li>\n<li>Deklariert ein Diagnoseereignis (Debouncing, DTC-Statusverarbeitung im <code>Dem</code>).</li>\n<li><em>Attribute:</em></li>\n<li><code>considerPtoStatus: Boolean [0..1]</code> – Berücksichtigung des Power Take-Off (Nebenantriebs-)Status für Fehlererkennung/MIL.</li>\n<li><code>dtcKind: DtcKindEnum [0..1]</code> – Klassifikation über Enumeration (<code>emissionRelatedDtc</code>, <code>nonEmmissionRelatedDtc</code>).</li>\n<li><code>obdDtcNumber: PositiveInteger [0..1]</code> – Spezifische OBD-DTC-Nummer.</li>\n<li><code>reportBehavior: ReportBehaviorEnum [0..1]</code> – Meldeverhalten des Diagnoseereignisses.</li>\n<li><code>udsDtcNumber: PositiveInteger [0..1]</code> – Spezifische UDS-DTC-Nummer.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+inhibitingFid</code> (<code>0..1</code>) zu <code>FunctionInhibitionNeeds</code>: Primärer Funktionsbezeichner (FID), der dieses Event bei aktivem Fehler inhibiert.</li>\n<li><code>+inhibitingSecondaryFid</code> (<code>0..*</code>) zu <code>FunctionInhibitionNeeds</code>: Sekundäre FIDs zur Kaskadierung von Inhibitionsbedingungen.</li>\n<li><code>+deferringFid</code> (<code>0..*</code>) zu <code>FunctionInhibitionNeeds</code>: FIDs zur Verzögerung der Fehlerreaktion/Fehlerspeicherung.</li>\n<li><strong><code>FunctionInhibitionNeeds</code></strong> (erbt direkt von <code>ServiceNeeds</code>):</li>\n<li>Repräsentiert die logische Entkopplung von Fehlererkennung und Fehlerreaktion über Function Identifiers (FIDs) im <code>FiM</code>.</li>\n</ul>\n<p class=\"fig-p\">#### OBD-spezifische Service-Bedarfe (Spezialisierungen von <code>DiagnosticCapabilityElement</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ObdRatioServiceNeeds</code></strong>:</li>\n<li>Konfiguriert das In-Use Monitor Performance Ratio (IUMPR) Tracking gemäß CARB/EPA-Gesetzgebung.</li>\n<li><em>Attribute:</em></li>\n<li><code>connectionType: ObdRatioConnectionKindEnum</code> – Steuerungsart (<code>apiUse</code> vs. <code>observer</code>).</li>\n<li><code>iumprGroup: NameToken [0..1]</code> – Gruppenzugehörigkeit des Monitors zur IUMPR-Clusterung.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+rateBasedMonitoredEvent</code> (<code>1</code>): Referenziert exakt ein übergeordnetes <code>DiagnosticEventNeeds</code>.</li>\n<li><code>+usedFid</code> (<code>0..1</code>) und <code>+usedSecondaryFid</code> (<code>0..*</code>): Referenziert <code>FunctionInhibitionNeeds</code>, deren Status für das Ratio relevant ist.</li>\n<li><strong><code>ObdPidServiceNeeds</code></strong>:</li>\n<li>Deklariert Bedarfe für Parameter Identifier (PID) Services nach OBD-II.</li>\n<li><em>Attribute:</em></li>\n<li><code>dataLength: PositiveInteger [0..1]</code> – Datenlänge des Parameters in Byte.</li>\n<li><code>parameterId: PositiveInteger [0..1]</code> – Kennung des PIDs.</li>\n<li><code>standard: String [0..1]</code> – Zugrundeliegender Standard (z. B. SAE J1979).</li>\n<li><strong><code>ObdInfoServiceNeeds</code></strong>:</li>\n<li>Spezifiziert Bedarfe bezüglich InfoType-Diensten (OBD Service $09).</li>\n<li><em>Attribute:</em></li>\n<li><code>dataLength: PositiveInteger [0..1]</code> – Datenlänge der InfoType-Nutzdaten.</li>\n<li><code>infoType: PositiveInteger [0..1]</code> – Numerische InfoType-Kennung.</li>\n<li><strong><code>ObdMonitorServiceNeeds</code></strong>:</li>\n<li>Beschreibt Service-Bedarfe für On-Board-Monitore (OBD Service $06).</li>\n<li><em>Attribute:</em></li>\n<li><code>onBoardMonitorId: PositiveInteger [0..1]</code> – Monitor-Identifier (OBDMID).</li>\n<li><code>testId: PositiveInteger [0..1]</code> – Test-Identifier (TID).</li>\n<li><code>unitAndScalingId: PositiveInteger [0..1]</code> – Skalierungs- und Einheitenbezeichner (UASID).</li>\n<li><strong><code>ObdControlServiceNeeds</code></strong>:</li>\n<li>Definiert Steuerungsanforderungen für Test-IDs im Rahmen von OBD.</li>\n<li><em>Attribute:</em></li>\n<li><code>testId: PositiveInteger [0..1]</code> – Test-Identifier für Prüfablaufsteuerung.</li>\n</ul>\n<p class=\"fig-p\">#### Aufzählungstypen (Enumerations)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ObdRatioConnectionKindEnum</code></strong>: Definiert die Anbindungsart (<code>apiUse</code>, <code>observer</code>).</li>\n<li><strong><code>DtcKindEnum</code></strong>: Unterscheidet Diagnosefehlercodes (<code>emissionRelatedDtc</code>, <code>nonEmmissionRelatedDtc</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell bildet statische Verträge ab, bestimmt jedoch folgende Laufzeitinteraktionen zwischen Applikation (<code>SW-C</code>), RTE und BSW-Modulen:</p>\n<ol class=\"fig-list\">\n<li><strong>Ereignis- & Fehlermeldung (<code>DiagnosticEventNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die SW-C setzt Diagnosestati asynchron via RTE über die Schnittstelle <code>DiagnosticMonitor</code> (<code>SetEventStatus</code>).</li>\n<li>Das <code>Dem</code> verarbeitet Entprellung und Statusbits (z. B. <code>TEST_FAILED</code>). Ist <code>dtcKind == emissionRelatedDtc</code>, werden MIL-Zähler, Freeze-Frame-Speicherung (Mode $02) und Fault-Memory-Abläufe forciert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Funktionsinhibition (<code>FunctionInhibitionNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schlägt ein Event fehl, aktiviert der <code>Dem</code> den hinterlegten Inhibitionszustand im <code>FiM</code>.</li>\n<li>Betroffene Komponenten prüfen vor Ausführung funktionsrelevanter Routinen über RTE (<code>FunctionInhibition</code>-Port) synchron via <code>GetFunctionPermission(FID, &amp;Permission)</code> die Freigabe.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>IUMPR-Berechnung (<code>ObdRatioServiceNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Modus <code>observer</code>:</strong> Das <code>Dem</code> detektiert Betriebsbedingungen selbstständig. Sobald die durch <code>usedFid</code> referenzierten FIDs fehlerfrei sind, wird der Denominator inkrementiert; schließt der Monitor über <code>DiagnosticEventNeeds</code> erfolgreich ab, wird der Numerator inkrementiert.</li>\n<li><strong>Modus <code>apiUse</code>:</strong> Die SW-C steuert Denominator- und Numerator-Fortschritt explizit durch Aufruf der RTE-APIs (z. B. <code>Dem_RepIUMPRDenLock</code>, <code>Dem_SetIUMPRDenCondition</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>OBD-Dienstabfrage (Services $01, $06, $08, $09):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein externer Tester fordert PIDs/TIDs über CAN/Ethernet an.</li>\n<li><code>Dcm</code> empfängt die Anfrage und ruft synchron oder asynchron die generierten Service-Ports der SW-C auf (z. B. <code>DataServices_OBD_*</code> für PID-Werte oder <code>CallbackDCMRequestControl</code> für Mode $08).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE- & BSW-Konfigurationskonsistenz (TPS_SWCT_1046):</strong></li>\n<li>Deklariert eine SW-C ein <code>ObdRatioServiceNeeds</code>, muss zwingend die Assoziation <code>+rateBasedMonitoredEvent</code> auf ein valides <code>DiagnosticEventNeeds</code> gesetzt sein.</li>\n<li>Fehlt die Zuordnung oder verweist sie auf ein nicht emissionsrelevantes Event (<code>dtcKind != emissionRelatedDtc</code>), verletzen Systemgeneratoren die Konfigurationsvalidierung für OBD-Konformität.</li>\n<li><strong>Vermeidung von Priority Inversion / Deadlocks bei FIDs:</strong></li>\n<li>Die Kopplung von <code>usedFid</code> an <code>ObdRatioServiceNeeds</code> verhindert das unzulässige Inkrementieren des IUMPR-Denominators, wenn vorgelagerte Diagnosen (z. B. Sensor-Plausibilität) die Durchführung des Monitors verhindern. Applikationsentwickler müssen FIDs so modellieren, dass zirkuläre Abhängigkeiten zwischen <code>inhibitingFid</code> und <code>usedFid</code> ausgeschlossen sind.</li>\n<li><strong>Port-Schnittstellenverträge:</strong></li>\n<li>Die Deklaration von <code>ObdPidServiceNeeds</code> bzw. <code>ObdInfoServiceNeeds</code> erzeugt zwingend typisierte Client-Server-Ports an der SW-C. Entwickler müssen sicherstellen, dass die Rückgabe-Payloads exakt der modellierten <code>dataLength</code> entsprechen, um PDU-Pufferüberläufe im <code>Dcm</code> zu verhindern.</li>\n</ul>"}, {"id": "FIG-853b357428bde6bc", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (M2-Metamodellausschnitt der AUTOSAR Template-Spezifikation <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition diagnostischer Service-Bedarfe (<code>ServiceNeeds</code>) von Software-Komponenten (SW-C) mit Schwerpunkt auf emissionsrelevanter On-Board-Diagnose (OBD-II nach SAE J1979 / ISO 15031, WWH-OBD nach ISO 27145) und Funktionsdeaktivierung (FIM).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient Generatoren (RTE- und BSW-Generatoren) als vertragliche Spezifikationsgrundlage zur automatischen Ableitung von RTE-Service-Ports (Client-Server / Sender-Receiver) sowie BSW-Modulkonfigurationen für <code>Dem</code> (Diagnostic Event Manager), <code>Dcm</code> (Diagnostic Communication Manager) und <code>FiM</code> (Function Inhibition Manager).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basisklassen & Metamodell-Verankerung</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwcServiceDependency</code></strong> (Spezialisierung von <code>ServiceDependency</code>, <code>Identifiable</code>, <code>AtpStructureElement</code>):</li>\n<li>Aggregiert kompositorisch über <code>+serviceNeeds</code> exakt eine Instanz (<code>1</code>) von <code>ServiceNeeds</code>. Verknüpft die Bedarfe mit konkreten SW-C-Ports oder internem Verhalten.</li>\n<li><strong><code>ServiceNeeds</code></strong> (abstrakt, <code>Identifiable</code>):</li>\n<li>Basisklasse für alle von einer SW-C deklarierten BSW-Dienstbedarfe.</li>\n<li><strong><code>DiagnosticCapabilityElement</code></strong> (abstrakt, erbt von <code>ServiceNeeds</code>):</li>\n<li>Gemeinsame Basis für diagnosebezogene Service-Bedarfe.</li>\n<li><em>Attribute:</em></li>\n<li><code>audience: DiagnosticAudienceEnum [0..*]</code> – Zielgruppe/Freigabekreis (z. B. Aftersales, Manufacturing).</li>\n<li><code>diagRequirement: DiagRequirementIdString [0..1]</code> – Rückverfolgbarkeits-ID zu gesetzlichen/funktionalen Anforderungen.</li>\n<li><code>securityAccessLevel: PositiveInteger [0..1]</code> – Erforderliche Sicherheitsstufe (Seed & Key gemäß UDS/OBD).</li>\n</ul>\n<p class=\"fig-p\">#### Diagnostische Ereignisse & Funktionsinhibition</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticEventNeeds</code></strong> (erbt von <code>DiagnosticCapabilityElement</code>):</li>\n<li>Deklariert ein Diagnoseereignis (Debouncing, DTC-Statusverarbeitung im <code>Dem</code>).</li>\n<li><em>Attribute:</em></li>\n<li><code>considerPtoStatus: Boolean [0..1]</code> – Berücksichtigung des Power Take-Off (Nebenantriebs-)Status für Fehlererkennung/MIL.</li>\n<li><code>dtcKind: DtcKindEnum [0..1]</code> – Klassifikation über Enumeration (<code>emissionRelatedDtc</code>, <code>nonEmmissionRelatedDtc</code>).</li>\n<li><code>obdDtcNumber: PositiveInteger [0..1]</code> – Spezifische OBD-DTC-Nummer.</li>\n<li><code>prestoredFreezeframeStoredInNvm: Boolean [0..1]</code> – Speicherung vorab erfasster Freeze-Frames im NVM.</li>\n<li><code>reportBehavior: ReportBehaviorEnum [0..1]</code> – Meldeverhalten des Diagnoseereignisses.</li>\n<li><code>udsDtcNumber: PositiveInteger [0..1]</code> – Spezifische UDS-DTC-Nummer.</li>\n<li><code>usesMonitorData: Boolean [0..1]</code> – Nutzung zusätzlicher Monitordaten.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+inhibitingFid</code> (<code>0..1</code>) zu <code>FunctionInhibitionNeeds</code>: Primärer Funktionsbezeichner (FID), der dieses Event bei aktivem Fehler inhibiert.</li>\n<li><code>+inhibitingSecondaryFid</code> (<code>0..*</code>) zu <code>FunctionInhibitionNeeds</code>: Sekundäre FIDs zur Kaskadierung von Inhibitionsbedingungen.</li>\n<li><code>+deferringFid</code> (<code>0..*</code>) zu <code>FunctionInhibitionNeeds</code>: FIDs zur Verzögerung der Fehlerreaktion/Fehlerspeicherung.</li>\n<li><strong><code>FunctionInhibitionNeeds</code></strong> (erbt direkt von <code>ServiceNeeds</code>):</li>\n<li>Repräsentiert die logische Entkopplung von Fehlererkennung und Fehlerreaktion über Function Identifiers (FIDs) im <code>FiM</code>.</li>\n</ul>\n<p class=\"fig-p\">#### OBD-spezifische Service-Bedarfe (Spezialisierungen von <code>DiagnosticCapabilityElement</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ObdRatioServiceNeeds</code></strong>:</li>\n<li>Konfiguriert das In-Use Monitor Performance Ratio (IUMPR) Tracking gemäß CARB/EPA-Gesetzgebung.</li>\n<li><em>Attribute:</em></li>\n<li><code>connectionType: ObdRatioConnectionKindEnum</code> – Steuerungsart (<code>apiUse</code> vs. <code>observer</code>).</li>\n<li><code>denominatorGroup: DiagnosticDenominatorConditionEnum [0..1]</code> – Zuordnung zu einer Nennerbedingungsgruppe.</li>\n<li><code>iumprGroup: NameToken [0..1]</code> – Gruppenzugehörigkeit des Monitors zur IUMPR-Clusterung.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+rateBasedMonitoredEvent</code> (<code>1</code>): Referenziert exakt ein übergeordnetes <code>DiagnosticEventNeeds</code>.</li>\n<li><code>+usedFid</code> (<code>0..1</code>) und <code>+usedSecondaryFid</code> (<code>0..*</code>): Referenziert <code>FunctionInhibitionNeeds</code>, deren Status für das Ratio relevant ist.</li>\n<li><strong><code>ObdRatioDenominatorNeeds</code></strong>:</li>\n<li>Definiert spezifische Nennerbedingungen für IUMPR.</li>\n<li><em>Attribute:</em></li>\n<li><code>denominatorCondition: DiagnosticDenominatorConditionEnum [0..1]</code> – Spezifische Bedingung zur Inkrementierung des Nenners.</li>\n<li><strong><code>ObdPidServiceNeeds</code></strong>:</li>\n<li>Deklariert Bedarfe für Parameter Identifier (PID) Services nach OBD-II.</li>\n<li><em>Attribute:</em></li>\n<li><code>dataLength: PositiveInteger [0..1]</code> – Datenlänge des Parameters in Byte.</li>\n<li><code>parameterId: PositiveInteger [0..1]</code> – Kennung des PIDs.</li>\n<li><code>standard: String [0..1]</code> – Zugrundeliegender Standard (z. B. SAE J1979).</li>\n<li><strong><code>ObdInfoServiceNeeds</code></strong>:</li>\n<li>Spezifiziert Bedarfe bezüglich InfoType-Diensten (OBD Service $09).</li>\n<li><em>Attribute:</em></li>\n<li><code>dataLength: PositiveInteger [0..1]</code> – Datenlänge der InfoType-Nutzdaten.</li>\n<li><code>infoType: PositiveInteger [0..1]</code> – Numerische InfoType-Kennung.</li>\n<li><strong><code>ObdMonitorServiceNeeds</code></strong>:</li>\n<li>Beschreibt Service-Bedarfe für On-Board-Monitore (OBD Service $06).</li>\n<li><em>Attribute:</em></li>\n<li><code>onBoardMonitorId: PositiveInteger [0..1]</code> – Monitor-Identifier (OBDMID).</li>\n<li><code>testId: PositiveInteger [0..1]</code> – Test-Identifier (TID).</li>\n<li><code>unitAndScalingId: PositiveInteger [0..1]</code> – Skalierungs- und Einheitenbezeichner (UASID).</li>\n<li><code>updateKind: DiagnosticMonitorUpdateKindEnum [0..1]</code> – Aktualisierungsmodus der Monitorwerte.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+eventNeeds</code> (<code>0..1</code>): Referenziert das zugehörige <code>DiagnosticEventNeeds</code>.</li>\n<li><strong><code>ObdControlServiceNeeds</code></strong>:</li>\n<li>Definiert Steuerungsanforderungen für Test-IDs im Rahmen von OBD.</li>\n<li><em>Attribute:</em></li>\n<li><code>testId: PositiveInteger [0..1]</code> – Test-Identifier für Prüfablaufsteuerung.</li>\n</ul>\n<p class=\"fig-p\">#### Aufzählungstypen (Enumerations)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ObdRatioConnectionKindEnum</code></strong>: Definiert die Anbindungsart (<code>apiUse</code>, <code>observer</code>).</li>\n<li><strong><code>DtcKindEnum</code></strong>: Unterscheidet Diagnosefehlercodes (<code>emissionRelatedDtc</code>, <code>nonEmmissionRelatedDtc</code>).</li>\n<li><strong><code>DiagnosticDenominatorConditionEnum</code></strong>: Nennerbedingungen (<code>coldstart</code>, <code>evap</code>, <code>500miles</code>, <code>individual</code>, <code>obd</code>).</li>\n<li><strong><code>DiagnosticMonitorUpdateKindEnum</code></strong>: Aktualisierungsverhalten des Monitors (<code>always</code>, <code>steady</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell bildet statische Verträge ab, bestimmt jedoch folgende Laufzeitinteraktionen zwischen Applikation (<code>SW-C</code>), RTE und BSW-Modulen:</p>\n<ol class=\"fig-list\">\n<li><strong>Ereignis- & Fehlermeldung (<code>DiagnosticEventNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die SW-C setzt Diagnosestati asynchron via RTE über die Schnittstelle <code>DiagnosticMonitor</code> (<code>SetEventStatus</code>).</li>\n<li>Das <code>Dem</code> verarbeitet Entprellung und Statusbits (z. B. <code>TEST_FAILED</code>). Ist <code>dtcKind == emissionRelatedDtc</code>, werden MIL-Zähler, Freeze-Frame-Speicherung (Mode $02) und Fault-Memory-Abläufe forciert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Funktionsinhibition (<code>FunctionInhibitionNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schlägt ein Event fehl, aktiviert der <code>Dem</code> den hinterlegten Inhibitionszustand im <code>FiM</code>.</li>\n<li>Betroffene Komponenten prüfen vor Ausführung funktionsrelevanter Routinen über RTE (<code>FunctionInhibition</code>-Port) synchron via <code>GetFunctionPermission(FID, &amp;Permission)</code> die Freigabe.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>IUMPR-Berechnung (<code>ObdRatioServiceNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Modus <code>observer</code>:</strong> Das <code>Dem</code> detektiert Betriebsbedingungen selbstständig. Sobald die durch <code>usedFid</code> referenzierten FIDs fehlerfrei sind, wird der Denominator inkrementiert; schließt der Monitor über <code>DiagnosticEventNeeds</code> erfolgreich ab, wird der Numerator inkrementiert.</li>\n<li><strong>Modus <code>apiUse</code>:</strong> Die SW-C steuert Denominator- und Numerator-Fortschritt explizit durch Aufruf der RTE-APIs (z. B. <code>Dem_RepIUMPRDenLock</code>, <code>Dem_SetIUMPRDenCondition</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>OBD-Dienstabfrage (Services $01, $06, $08, $09):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein externer Tester fordert PIDs/TIDs über CAN/Ethernet an.</li>\n<li><code>Dcm</code> empfängt die Anfrage und ruft synchron oder asynchron die generierten Service-Ports der SW-C auf (z. B. <code>DataServices_OBD_*</code> für PID-Werte oder <code>CallbackDCMRequestControl</code> für Mode $08).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE- & BSW-Konfigurationskonsistenz (TPS_SWCT_1046):</strong></li>\n<li>Deklariert eine SW-C ein <code>ObdRatioServiceNeeds</code>, muss zwingend die Assoziation <code>+rateBasedMonitoredEvent</code> auf ein valides <code>DiagnosticEventNeeds</code> gesetzt sein.</li>\n<li>Fehlt die Zuordnung oder verweist sie auf ein nicht emissionsrelevantes Event (<code>dtcKind != emissionRelatedDtc</code>), verletzen Systemgeneratoren die Konfigurationsvalidierung für OBD-Konformität.</li>\n<li><strong>Vermeidung von Priority Inversion / Deadlocks bei FIDs:</strong></li>\n<li>Die Kopplung von <code>usedFid</code> an <code>ObdRatioServiceNeeds</code> verhindert das unzulässige Inkrementieren des IUMPR-Denominators, wenn vorgelagerte Diagnosen (z. B. Sensor-Plausibilität) die Durchführung des Monitors verhindern. Applikationsentwickler müssen FIDs so modellieren, dass zirkuläre Abhängigkeiten zwischen <code>inhibitingFid</code> und <code>usedFid</code> ausgeschlossen sind.</li>\n<li><strong>Port-Schnittstellenverträge:</strong></li>\n<li>Die Deklaration von <code>ObdPidServiceNeeds</code> bzw. <code>ObdInfoServiceNeeds</code> erzeugt zwingend typisierte Client-Server-Ports an der SW-C. Entwickler müssen sicherstellen, dass die Rückgabe-Payloads exakt der modellierten <code>dataLength</code> entsprechen, um PDU-Pufferüberläufe im <code>Dcm</code> zu verhindern.</li>\n</ul>"}, {"id": "FIG-921a2c30bcb6373b", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (M2-Metamodellausschnitt der AUTOSAR Template-Spezifikation <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition diagnostischer Service-Bedarfe (<code>ServiceNeeds</code>) von Software-Komponenten (SW-C) mit Schwerpunkt auf emissionsrelevanter On-Board-Diagnose (OBD-II nach SAE J1979 / ISO 15031, WWH-OBD nach ISO 27145) und Funktionsdeaktivierung (FIM).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient Generatoren (RTE- und BSW-Generatoren) als vertragliche Spezifikationsgrundlage zur automatischen Ableitung von RTE-Service-Ports (Client-Server / Sender-Receiver) sowie BSW-Modulkonfigurationen für <code>Dem</code> (Diagnostic Event Manager), <code>Dcm</code> (Diagnostic Communication Manager) und <code>FiM</code> (Function Inhibition Manager).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basisklassen & Metamodell-Verankerung</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwcServiceDependency</code></strong> (Spezialisierung von <code>ServiceDependency</code>, <code>Identifiable</code>, <code>AtpStructureElement</code>):</li>\n<li>Aggregiert kompositorisch über <code>+serviceNeeds</code> exakt eine Instanz (<code>1</code>) von <code>ServiceNeeds</code>. Verknüpft die Bedarfe mit konkreten SW-C-Ports oder internem Verhalten.</li>\n<li><strong><code>ServiceNeeds</code></strong> (abstrakt, <code>Identifiable</code>):</li>\n<li>Basisklasse für alle von einer SW-C deklarierten BSW-Dienstbedarfe.</li>\n<li><strong><code>DiagnosticCapabilityElement</code></strong> (abstrakt, erbt von <code>ServiceNeeds</code>):</li>\n<li>Gemeinsame Basis für diagnosebezogene Service-Bedarfe.</li>\n<li><em>Attribute:</em></li>\n<li><code>audience: DiagnosticAudienceEnum [0..*]</code> – Zielgruppe/Freigabekreis (z. B. Aftersales, Manufacturing).</li>\n<li><code>diagRequirement: DiagRequirementIdString [0..1]</code> – Rückverfolgbarkeits-ID zu gesetzlichen/funktionalen Anforderungen.</li>\n<li><code>securityAccessLevel: PositiveInteger [0..1]</code> – Erforderliche Sicherheitsstufe (Seed & Key gemäß UDS/OBD).</li>\n</ul>\n<p class=\"fig-p\">#### Diagnostische Ereignisse & Funktionsinhibition</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticEventNeeds</code></strong> (erbt von <code>DiagnosticCapabilityElement</code>):</li>\n<li>Deklariert ein Diagnoseereignis (Debouncing, DTC-Statusverarbeitung im <code>Dem</code>).</li>\n<li><em>Attribute:</em></li>\n<li><code>considerPtoStatus: Boolean [0..1]</code> – Berücksichtigung des Power Take-Off (Nebenantriebs-)Status für Fehlererkennung/MIL.</li>\n<li><code>dtcKind: DtcKindEnum [0..1]</code> – Klassifikation über Enumeration (<code>emissionRelatedDtc</code>, <code>nonEmmissionRelatedDtc</code>).</li>\n<li><code>obdDtcNumber: PositiveInteger [0..1]</code> – Spezifische OBD-DTC-Nummer.</li>\n<li><code>prestoredFreezeframeStoredInNvm: Boolean [0..1]</code> – Speicherung vorab erfasster Freeze-Frames im NVM.</li>\n<li><code>reportBehavior: ReportBehaviorEnum [0..1]</code> – Meldeverhalten des Diagnoseereignisses.</li>\n<li><code>udsDtcNumber: PositiveInteger [0..1]</code> – Spezifische UDS-DTC-Nummer.</li>\n<li><code>usesMonitorData: Boolean [0..1]</code> – Nutzung zusätzlicher Monitordaten.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+inhibitingFid</code> (<code>0..1</code>) zu <code>FunctionInhibitionNeeds</code>: Primärer Funktionsbezeichner (FID), der dieses Event bei aktivem Fehler inhibiert.</li>\n<li><code>+inhibitingSecondaryFid</code> (<code>0..*</code>) zu <code>FunctionInhibitionNeeds</code>: Sekundäre FIDs zur Kaskadierung von Inhibitionsbedingungen.</li>\n<li><code>+deferringFid</code> (<code>0..*</code>) zu <code>FunctionInhibitionNeeds</code>: FIDs zur Verzögerung der Fehlerreaktion/Fehlerspeicherung.</li>\n<li><strong><code>FunctionInhibitionNeeds</code></strong> (erbt direkt von <code>ServiceNeeds</code>):</li>\n<li>Repräsentiert die logische Entkopplung von Fehlererkennung und Fehlerreaktion über Function Identifiers (FIDs) im <code>FiM</code>.</li>\n</ul>\n<p class=\"fig-p\">#### OBD-spezifische Service-Bedarfe (Spezialisierungen von <code>DiagnosticCapabilityElement</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ObdRatioServiceNeeds</code></strong>:</li>\n<li>Konfiguriert das In-Use Monitor Performance Ratio (IUMPR) Tracking gemäß CARB/EPA-Gesetzgebung.</li>\n<li><em>Attribute:</em></li>\n<li><code>connectionType: ObdRatioConnectionKindEnum</code> – Steuerungsart (<code>apiUse</code> vs. <code>observer</code>).</li>\n<li><code>denominatorGroup: DiagnosticDenominatorConditionEnum [0..1]</code> – Zuordnung zu einer Nennerbedingungsgruppe.</li>\n<li><code>iumprGroup: NameToken [0..1]</code> – Gruppenzugehörigkeit des Monitors zur IUMPR-Clusterung.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+rateBasedMonitoredEvent</code> (<code>1</code>): Referenziert exakt ein übergeordnetes <code>DiagnosticEventNeeds</code>.</li>\n<li><code>+usedFid</code> (<code>0..1</code>) und <code>+usedSecondaryFid</code> (<code>0..*</code>): Referenziert <code>FunctionInhibitionNeeds</code>, deren Status für das Ratio relevant ist.</li>\n<li><strong><code>ObdRatioDenominatorNeeds</code></strong>:</li>\n<li>Definiert spezifische Nennerbedingungen für IUMPR.</li>\n<li><em>Attribute:</em></li>\n<li><code>denominatorCondition: DiagnosticDenominatorConditionEnum [0..1]</code> – Spezifische Bedingung zur Inkrementierung des Nenners.</li>\n<li><strong><code>ObdPidServiceNeeds</code></strong>:</li>\n<li>Deklariert Bedarfe für Parameter Identifier (PID) Services nach OBD-II.</li>\n<li><em>Attribute:</em></li>\n<li><code>dataLength: PositiveInteger [0..1]</code> – Datenlänge des Parameters in Byte.</li>\n<li><code>parameterId: PositiveInteger [0..1]</code> – Kennung des PIDs.</li>\n<li><code>standard: String [0..1]</code> – Zugrundeliegender Standard (z. B. SAE J1979).</li>\n<li><strong><code>ObdInfoServiceNeeds</code></strong>:</li>\n<li>Spezifiziert Bedarfe bezüglich InfoType-Diensten (OBD Service $09).</li>\n<li><em>Attribute:</em></li>\n<li><code>dataLength: PositiveInteger [0..1]</code> – Datenlänge der InfoType-Nutzdaten.</li>\n<li><code>infoType: PositiveInteger [0..1]</code> – Numerische InfoType-Kennung.</li>\n<li><strong><code>ObdMonitorServiceNeeds</code></strong>:</li>\n<li>Beschreibt Service-Bedarfe für On-Board-Monitore (OBD Service $06).</li>\n<li><em>Attribute:</em></li>\n<li><code>onBoardMonitorId: PositiveInteger [0..1]</code> – Monitor-Identifier (OBDMID).</li>\n<li><code>testId: PositiveInteger [0..1]</code> – Test-Identifier (TID).</li>\n<li><code>unitAndScalingId: PositiveInteger [0..1]</code> – Skalierungs- und Einheitenbezeichner (UASID).</li>\n<li><code>updateKind: DiagnosticMonitorUpdateKindEnum [0..1]</code> – Aktualisierungsmodus der Monitorwerte.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+eventNeeds</code> (<code>0..1</code>): Referenziert das zugehörige <code>DiagnosticEventNeeds</code>.</li>\n<li><strong><code>ObdControlServiceNeeds</code></strong>:</li>\n<li>Definiert Steuerungsanforderungen für Test-IDs im Rahmen von OBD.</li>\n<li><em>Attribute:</em></li>\n<li><code>testId: PositiveInteger [0..1]</code> – Test-Identifier für Prüfablaufsteuerung.</li>\n</ul>\n<p class=\"fig-p\">#### Aufzählungstypen (Enumerations)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ObdRatioConnectionKindEnum</code></strong>: Definiert die Anbindungsart (<code>apiUse</code>, <code>observer</code>).</li>\n<li><strong><code>DtcKindEnum</code></strong>: Unterscheidet Diagnosefehlercodes (<code>emissionRelatedDtc</code>, <code>nonEmmissionRelatedDtc</code>).</li>\n<li><strong><code>DiagnosticDenominatorConditionEnum</code></strong>: Nennerbedingungen (<code>coldstart</code>, <code>evap</code>, <code>500miles</code>, <code>individual</code>, <code>obd</code>).</li>\n<li><strong><code>DiagnosticMonitorUpdateKindEnum</code></strong>: Aktualisierungsverhalten des Monitors (<code>always</code>, <code>steady</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell bildet statische Verträge ab, bestimmt jedoch folgende Laufzeitinteraktionen zwischen Applikation (<code>SW-C</code>), RTE und BSW-Modulen:</p>\n<ol class=\"fig-list\">\n<li><strong>Ereignis- & Fehlermeldung (<code>DiagnosticEventNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die SW-C setzt Diagnosestati asynchron via RTE über die Schnittstelle <code>DiagnosticMonitor</code> (<code>SetEventStatus</code>).</li>\n<li>Das <code>Dem</code> verarbeitet Entprellung und Statusbits (z. B. <code>TEST_FAILED</code>). Ist <code>dtcKind == emissionRelatedDtc</code>, werden MIL-Zähler, Freeze-Frame-Speicherung (Mode $02) und Fault-Memory-Abläufe forciert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Funktionsinhibition (<code>FunctionInhibitionNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schlägt ein Event fehl, aktiviert der <code>Dem</code> den hinterlegten Inhibitionszustand im <code>FiM</code>.</li>\n<li>Betroffene Komponenten prüfen vor Ausführung funktionsrelevanter Routinen über RTE (<code>FunctionInhibition</code>-Port) synchron via <code>GetFunctionPermission(FID, &amp;Permission)</code> die Freigabe.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>IUMPR-Berechnung (<code>ObdRatioServiceNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Modus <code>observer</code>:</strong> Das <code>Dem</code> detektiert Betriebsbedingungen selbstständig. Sobald die durch <code>usedFid</code> referenzierten FIDs fehlerfrei sind, wird der Denominator inkrementiert; schließt der Monitor über <code>DiagnosticEventNeeds</code> erfolgreich ab, wird der Numerator inkrementiert.</li>\n<li><strong>Modus <code>apiUse</code>:</strong> Die SW-C steuert Denominator- und Numerator-Fortschritt explizit durch Aufruf der RTE-APIs (z. B. <code>Dem_RepIUMPRDenLock</code>, <code>Dem_SetIUMPRDenCondition</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>OBD-Dienstabfrage (Services $01, $06, $08, $09):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein externer Tester fordert PIDs/TIDs über CAN/Ethernet an.</li>\n<li><code>Dcm</code> empfängt die Anfrage und ruft synchron oder asynchron die generierten Service-Ports der SW-C auf (z. B. <code>DataServices_OBD_*</code> für PID-Werte oder <code>CallbackDCMRequestControl</code> für Mode $08).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE- & BSW-Konfigurationskonsistenz (TPS_SWCT_1046):</strong></li>\n<li>Deklariert eine SW-C ein <code>ObdRatioServiceNeeds</code>, muss zwingend die Assoziation <code>+rateBasedMonitoredEvent</code> auf ein valides <code>DiagnosticEventNeeds</code> gesetzt sein.</li>\n<li>Fehlt die Zuordnung oder verweist sie auf ein nicht emissionsrelevantes Event (<code>dtcKind != emissionRelatedDtc</code>), verletzen Systemgeneratoren die Konfigurationsvalidierung für OBD-Konformität.</li>\n<li><strong>Vermeidung von Priority Inversion / Deadlocks bei FIDs:</strong></li>\n<li>Die Kopplung von <code>usedFid</code> an <code>ObdRatioServiceNeeds</code> verhindert das unzulässige Inkrementieren des IUMPR-Denominators, wenn vorgelagerte Diagnosen (z. B. Sensor-Plausibilität) die Durchführung des Monitors verhindern. Applikationsentwickler müssen FIDs so modellieren, dass zirkuläre Abhängigkeiten zwischen <code>inhibitingFid</code> und <code>usedFid</code> ausgeschlossen sind.</li>\n<li><strong>Port-Schnittstellenverträge:</strong></li>\n<li>Die Deklaration von <code>ObdPidServiceNeeds</code> bzw. <code>ObdInfoServiceNeeds</code> erzeugt zwingend typisierte Client-Server-Ports an der SW-C. Entwickler müssen sicherstellen, dass die Rückgabe-Payloads exakt der modellierten <code>dataLength</code> entsprechen, um PDU-Pufferüberläufe im <code>Dcm</code> zu verhindern.</li>\n</ul>"}, {"id": "FIG-f0baf71606385c89", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (M2-Metamodellausschnitt der AUTOSAR Template-Spezifikation <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition diagnostischer Service-Bedarfe (<code>ServiceNeeds</code>) von Software-Komponenten (SW-C) mit Schwerpunkt auf emissionsrelevanter On-Board-Diagnose (OBD-II nach SAE J1979 / ISO 15031, WWH-OBD nach ISO 27145) und Funktionsdeaktivierung (FIM).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient Generatoren (RTE- und BSW-Generatoren) als vertragliche Spezifikationsgrundlage zur automatischen Ableitung von RTE-Service-Ports (Client-Server / Sender-Receiver) sowie BSW-Modulkonfigurationen für <code>Dem</code> (Diagnostic Event Manager), <code>Dcm</code> (Diagnostic Communication Manager) und <code>FiM</code> (Function Inhibition Manager).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basisklassen & Metamodell-Verankerung</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwcServiceDependency</code></strong> (Spezialisierung von <code>ServiceDependency</code>, <code>Identifiable</code>, <code>AtpStructureElement</code>):</li>\n<li>Aggregiert kompositorisch über <code>+serviceNeeds</code> optional eine Instanz (<code>0..1</code>) von <code>ServiceNeeds</code>. Verknüpft die Bedarfe mit konkreten SW-C-Ports oder internem Verhalten.</li>\n<li><strong><code>ServiceNeeds</code></strong> (abstrakt, <code>Identifiable</code>):</li>\n<li>Basisklasse für alle von einer SW-C deklarierten BSW-Dienstbedarfe.</li>\n<li><strong><code>DiagnosticCapabilityElement</code></strong> (abstrakt, erbt von <code>ServiceNeeds</code>):</li>\n<li>Gemeinsame Basis für diagnosebezogene Service-Bedarfe.</li>\n<li><em>Attribute:</em></li>\n<li><code>audience: DiagnosticAudienceEnum [0..*]</code> – Zielgruppe/Freigabekreis (z. B. Aftersales, Manufacturing).</li>\n<li><code>diagRequirement: DiagRequirementIdString [0..1]</code> – Rückverfolgbarkeits-ID zu gesetzlichen/funktionalen Anforderungen.</li>\n<li><code>securityAccessLevel: PositiveInteger [0..1]</code> – Erforderliche Sicherheitsstufe (Seed & Key gemäß UDS/OBD).</li>\n</ul>\n<p class=\"fig-p\">#### Diagnostische Ereignisse & Funktionsinhibition</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticEventNeeds</code></strong> (erbt von <code>DiagnosticCapabilityElement</code>):</li>\n<li>Deklariert ein Diagnoseereignis (Debouncing, DTC-Statusverarbeitung im <code>Dem</code>).</li>\n<li><em>Attribute:</em></li>\n<li><code>considerPtoStatus: Boolean [0..1]</code> – Berücksichtigung des Power Take-Off (Nebenantriebs-)Status für Fehlererkennung/MIL.</li>\n<li><code>dtcKind: DtcKindEnum [0..1]</code> – Klassifikation über Enumeration (<code>emissionRelatedDtc</code>, <code>nonEmmissionRelatedDtc</code>).</li>\n<li><code>obdDtcNumber: PositiveInteger [0..1]</code> – Spezifische OBD-DTC-Nummer.</li>\n<li><code>prestoredFreezeframeStoredInNvm: Boolean [0..1]</code> – Speicherung vorab erfasster Freeze-Frames im NVM.</li>\n<li><code>reportBehavior: ReportBehaviorEnum [0..1]</code> – Meldeverhalten des Diagnoseereignisses.</li>\n<li><code>udsDtcNumber: PositiveInteger [0..1]</code> – Spezifische UDS-DTC-Nummer.</li>\n<li><code>usesMonitorData: Boolean [0..1]</code> – Nutzung zusätzlicher Monitordaten.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+deferringFid</code> (<code>0..*</code>) zu <code>FunctionInhibitionNeeds</code>: FIDs zur Verzögerung der Fehlerreaktion/Fehlerspeicherung.</li>\n<li><strong><code>FunctionInhibitionNeeds</code></strong> (erbt direkt von <code>ServiceNeeds</code>):</li>\n<li>Repräsentiert die logische Entkopplung von Fehlererkennung und Fehlerreaktion über Function Identifiers (FIDs) im <code>FiM</code>.</li>\n</ul>\n<p class=\"fig-p\">#### OBD-spezifische Service-Bedarfe (Spezialisierungen von <code>DiagnosticCapabilityElement</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ObdRatioServiceNeeds</code></strong>:</li>\n<li>Konfiguriert das In-Use Monitor Performance Ratio (IUMPR) Tracking gemäß CARB/EPA-Gesetzgebung.</li>\n<li><em>Attribute:</em></li>\n<li><code>connectionType: ObdRatioConnectionKindEnum [0..1]</code> – Steuerungsart (<code>apiUse</code> vs. <code>observer</code>).</li>\n<li><code>denominatorGroup: DiagnosticDenominatorConditionEnum [0..1]</code> – Zuordnung zu einer Nennerbedingungsgruppe.</li>\n<li><code>iumprGroup: NameToken [0..1]</code> – Gruppenzugehörigkeit des Monitors zur IUMPR-Clusterung.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+rateBasedMonitoredEvent</code> (<code>0..1</code>): Referenziert optional ein übergeordnetes <code>DiagnosticEventNeeds</code>.</li>\n<li><code>+usedFid</code> (<code>0..1</code>): Referenziert <code>FunctionInhibitionNeeds</code>, deren Status für das Ratio relevant ist.</li>\n<li><strong><code>ObdRatioDenominatorNeeds</code></strong>:</li>\n<li>Definiert spezifische Nennerbedingungen für IUMPR.</li>\n<li><em>Attribute:</em></li>\n<li><code>denominatorCondition: DiagnosticDenominatorConditionEnum [0..1]</code> – Spezifische Bedingung zur Inkrementierung des Nenners.</li>\n<li><strong><code>ObdPidServiceNeeds</code></strong>:</li>\n<li>Deklariert Bedarfe für Parameter Identifier (PID) Services nach OBD-II.</li>\n<li><em>Attribute:</em></li>\n<li><code>dataLength: PositiveInteger [0..1]</code> – Datenlänge des Parameters in Byte.</li>\n<li><code>parameterId: PositiveInteger [0..1]</code> – Kennung des PIDs.</li>\n<li><code>standard: String [0..1]</code> – Zugrundeliegender Standard (z. B. SAE J1979).</li>\n<li><strong><code>ObdInfoServiceNeeds</code></strong>:</li>\n<li>Spezifiziert Bedarfe bezüglich InfoType-Diensten (OBD Service $09).</li>\n<li><em>Attribute:</em></li>\n<li><code>dataLength: PositiveInteger [0..1]</code> – Datenlänge der InfoType-Nutzdaten.</li>\n<li><code>infoType: PositiveInteger [0..1]</code> – Numerische InfoType-Kennung.</li>\n<li><strong><code>ObdMonitorServiceNeeds</code></strong>:</li>\n<li>Beschreibt Service-Bedarfe für On-Board-Monitore (OBD Service $06).</li>\n<li><em>Attribute:</em></li>\n<li><code>onBoardMonitorId: PositiveInteger [0..1]</code> – Monitor-Identifier (OBDMID).</li>\n<li><code>testId: PositiveInteger [0..1]</code> – Test-Identifier (TID).</li>\n<li><code>unitAndScalingId: PositiveInteger [0..1]</code> – Skalierungs- und Einheitenbezeichner (UASID).</li>\n<li><code>updateKind: DiagnosticMonitorUpdateKindEnum [0..1]</code> – Aktualisierungsmodus der Monitorwerte.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+eventNeeds</code> (<code>0..1</code>): Referenziert das zugehörige <code>DiagnosticEventNeeds</code>.</li>\n<li><strong><code>ObdControlServiceNeeds</code></strong>:</li>\n<li>Definiert Steuerungsanforderungen für Test-IDs im Rahmen von OBD.</li>\n<li><em>Attribute:</em></li>\n<li><code>testId: PositiveInteger [0..1]</code> – Test-Identifier für Prüfablaufsteuerung.</li>\n</ul>\n<p class=\"fig-p\">#### Aufzählungstypen (Enumerations)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ObdRatioConnectionKindEnum</code></strong>: Definiert die Anbindungsart (<code>apiUse</code>, <code>observer</code>).</li>\n<li><strong><code>DtcKindEnum</code></strong>: Unterscheidet Diagnosefehlercodes (<code>emissionRelatedDtc</code>, <code>nonEmmissionRelatedDtc</code>).</li>\n<li><strong><code>DiagnosticDenominatorConditionEnum</code></strong>: Nennerbedingungen (<code>coldstart</code>, <code>evap</code>, <code>500miles</code>, <code>individual</code>, <code>obd</code>).</li>\n<li><strong><code>DiagnosticMonitorUpdateKindEnum</code></strong>: Aktualisierungsverhalten des Monitors (<code>always</code>, <code>steady</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell bildet statische Verträge ab, bestimmt jedoch folgende Laufzeitinteraktionen zwischen Applikation (<code>SW-C</code>), RTE und BSW-Modulen:</p>\n<ol class=\"fig-list\">\n<li><strong>Ereignis- & Fehlermeldung (<code>DiagnosticEventNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die SW-C setzt Diagnosestati asynchron via RTE über die Schnittstelle <code>DiagnosticMonitor</code> (<code>SetEventStatus</code>).</li>\n<li>Das <code>Dem</code> verarbeitet Entprellung und Statusbits (z. B. <code>TEST_FAILED</code>). Ist <code>dtcKind == emissionRelatedDtc</code>, werden MIL-Zähler, Freeze-Frame-Speicherung (Mode $02) und Fault-Memory-Abläufe forciert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Funktionsinhibition (<code>FunctionInhibitionNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schlägt ein Event fehl, aktiviert der <code>Dem</code> den hinterlegten Inhibitionszustand im <code>FiM</code>.</li>\n<li>Betroffene Komponenten prüfen vor Ausführung funktionsrelevanter Routinen über RTE (<code>FunctionInhibition</code>-Port) synchron via <code>GetFunctionPermission(FID, &amp;Permission)</code> die Freigabe.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>IUMPR-Berechnung (<code>ObdRatioServiceNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Modus <code>observer</code>:</strong> Das <code>Dem</code> detektiert Betriebsbedingungen selbstständig. Sobald die durch <code>usedFid</code> referenzierten FIDs fehlerfrei sind, wird der Denominator inkrementiert; schließt der Monitor über <code>DiagnosticEventNeeds</code> erfolgreich ab, wird der Numerator inkrementiert.</li>\n<li><strong>Modus <code>apiUse</code>:</strong> Die SW-C steuert Denominator- und Numerator-Fortschritt explizit durch Aufruf der RTE-APIs (z. B. <code>Dem_RepIUMPRDenLock</code>, <code>Dem_SetIUMPRDenCondition</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>OBD-Dienstabfrage (Services $01, $06, $08, $09):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein externer Tester fordert PIDs/TIDs über CAN/Ethernet an.</li>\n<li><code>Dcm</code> empfängt die Anfrage und ruft synchron oder asynchron die generierten Service-Ports der SW-C auf (z. B. <code>DataServices_OBD_*</code> für PID-Werte oder <code>CallbackDCMRequestControl</code> für Mode $08).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE- & BSW-Konfigurationskonsistenz (TPS_SWCT_1046):</strong></li>\n<li>Deklariert eine SW-C ein <code>ObdRatioServiceNeeds</code>, muss zwingend die Assoziation <code>+rateBasedMonitoredEvent</code> auf ein valides <code>DiagnosticEventNeeds</code> gesetzt sein.</li>\n<li>Fehlt die Zuordnung oder verweist sie auf ein nicht emissionsrelevantes Event (<code>dtcKind != emissionRelatedDtc</code>), verletzen Systemgeneratoren die Konfigurationsvalidierung für OBD-Konformität.</li>\n<li><strong>Vermeidung von Priority Inversion / Deadlocks bei FIDs:</strong></li>\n<li>Die Kopplung von <code>usedFid</code> an <code>ObdRatioServiceNeeds</code> verhindert das unzulässige Inkrementieren des IUMPR-Denominators, wenn vorgelagerte Diagnosen (z. B. Sensor-Plausibilität) die Durchführung des Monitors verhindern. Applikationsentwickler müssen FIDs so modellieren, dass zirkuläre Abhängigkeiten zwischen <code>inhibitingFid</code> und <code>usedFid</code> ausgeschlossen sind.</li>\n<li><strong>Port-Schnittstellenverträge:</strong></li>\n<li>Die Deklaration von <code>ObdPidServiceNeeds</code> bzw. <code>ObdInfoServiceNeeds</code> erzeugt zwingend typisierte Client-Server-Ports an der SW-C. Entwickler müssen sicherstellen, dass die Rückgabe-Payloads exakt der modellierten <code>dataLength</code> entsprechen, um PDU-Pufferüberläufe im <code>Dcm</code> zu verhindern.</li>\n</ul>"}, {"id": "FIG-411a6b54ec9c4afc", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (M2-Metamodellausschnitt der AUTOSAR Template-Spezifikation <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition diagnostischer Service-Bedarfe (<code>ServiceNeeds</code>) von Software-Komponenten (SW-C) mit Schwerpunkt auf emissionsrelevanter On-Board-Diagnose (OBD-II nach SAE J1979 / ISO 15031, WWH-OBD nach ISO 27145) und Funktionsdeaktivierung (FIM).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient Generatoren (RTE- und BSW-Generatoren) als vertragliche Spezifikationsgrundlage zur automatischen Ableitung von RTE-Service-Ports (Client-Server / Sender-Receiver) sowie BSW-Modulkonfigurationen für <code>Dem</code> (Diagnostic Event Manager), <code>Dcm</code> (Diagnostic Communication Manager) und <code>FiM</code> (Function Inhibition Manager).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basisklassen & Metamodell-Verankerung</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwcServiceDependency</code></strong> (Spezialisierung von <code>ServiceDependency</code>, <code>Identifiable</code>, <code>AtpStructureElement</code>):</li>\n<li>Aggregiert kompositorisch über <code>+serviceNeeds</code> optional eine Instanz (<code>0..1</code>) von <code>ServiceNeeds</code>. Verknüpft die Bedarfe mit konkreten SW-C-Ports oder internem Verhalten.</li>\n<li><strong><code>ServiceNeeds</code></strong> (abstrakt, <code>Identifiable</code>):</li>\n<li>Basisklasse für alle von einer SW-C deklarierten BSW-Dienstbedarfe.</li>\n<li><strong><code>DiagnosticCapabilityElement</code></strong> (abstrakt, erbt von <code>ServiceNeeds</code>):</li>\n<li>Gemeinsame Basis für diagnosebezogene Service-Bedarfe.</li>\n<li><em>Attribute:</em></li>\n<li><code>audience: DiagnosticAudienceEnum [0..*]</code> – Zielgruppe/Freigabekreis (z. B. Aftersales, Manufacturing).</li>\n<li><code>diagRequirement: DiagRequirementIdString [0..1]</code> – Rückverfolgbarkeits-ID zu gesetzlichen/funktionalen Anforderungen.</li>\n<li><code>securityAccessLevel: PositiveInteger [0..1]</code> – Erforderliche Sicherheitsstufe (Seed & Key gemäß UDS/OBD).</li>\n</ul>\n<p class=\"fig-p\">#### Diagnostische Ereignisse & Funktionsinhibition</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticEventNeeds</code></strong> (erbt von <code>DiagnosticCapabilityElement</code>):</li>\n<li>Deklariert ein Diagnoseereignis (Debouncing, DTC-Statusverarbeitung im <code>Dem</code>).</li>\n<li><em>Attribute:</em></li>\n<li><code>prestoredFreezeframeStoredInNvm: Boolean [0..1]</code> – Speicherung vorab erfasster Freeze-Frames im NVM.</li>\n<li><code>usesMonitorData: Boolean [0..1]</code> – Nutzung zusätzlicher Monitordaten.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+deferringFid</code> (<code>0..*</code>) zu <code>FunctionInhibitionNeeds</code>: FIDs zur Verzögerung der Fehlerreaktion/Fehlerspeicherung.</li>\n<li><strong><code>FunctionInhibitionNeeds</code></strong> (erbt direkt von <code>ServiceNeeds</code>):</li>\n<li>Repräsentiert die logische Entkopplung von Fehlererkennung und Fehlerreaktion über Function Identifiers (FIDs) im <code>FiM</code>.</li>\n</ul>\n<p class=\"fig-p\">#### OBD-spezifische Service-Bedarfe (Spezialisierungen von <code>DiagnosticCapabilityElement</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ObdRatioServiceNeeds</code></strong>:</li>\n<li>Konfiguriert das In-Use Monitor Performance Ratio (IUMPR) Tracking gemäß CARB/EPA-Gesetzgebung.</li>\n<li><em>Attribute:</em></li>\n<li><code>connectionType: ObdRatioConnectionKindEnum [0..1]</code> – Steuerungsart (<code>apiUse</code> vs. <code>observer</code>).</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+rateBasedMonitoredEvent</code> (<code>0..1</code>): Referenziert optional ein übergeordnetes <code>DiagnosticEventNeeds</code>.</li>\n<li><code>+usedFid</code> (<code>0..1</code>): Referenziert <code>FunctionInhibitionNeeds</code>, deren Status für das Ratio relevant ist.</li>\n<li><strong><code>ObdRatioDenominatorNeeds</code></strong>:</li>\n<li>Definiert spezifische Nennerbedingungen für IUMPR.</li>\n<li><em>Attribute:</em></li>\n<li><code>denominatorCondition: DiagnosticDenominatorConditionEnum [0..1]</code> – Spezifische Bedingung zur Inkrementierung des Nenners.</li>\n<li><strong><code>ObdPidServiceNeeds</code></strong>:</li>\n<li>Deklariert Bedarfe für Parameter Identifier (PID) Services nach OBD-II ohne eigene Attributspezifikation im Diagramm.</li>\n<li><strong><code>ObdInfoServiceNeeds</code></strong>:</li>\n<li>Spezifiziert Bedarfe bezüglich InfoType-Diensten (OBD Service $09) ohne eigene Attributspezifikation im Diagramm.</li>\n<li><strong><code>ObdControlServiceNeeds</code></strong>:</li>\n<li>Definiert Steuerungsanforderungen für Test-IDs im Rahmen von OBD ohne eigene Attributspezifikation im Diagramm.</li>\n<li><strong><code>ObdMonitorServiceNeeds</code></strong>:</li>\n<li>Beschreibt Service-Bedarfe für On-Board-Monitore (OBD Service $06).</li>\n<li><em>Attribute:</em></li>\n<li><code>unitAndScalingId: PositiveInteger [0..1]</code> – Skalierungs- und Einheitenbezeichner (UASID).</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+eventNeeds</code> (<code>0..1</code>): Referenziert das zugehörige <code>DiagnosticEventNeeds</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Aufzählungstypen (Enumerations)</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticDenominatorConditionEnum</code></strong>: Nennerbedingungen (<code>coldstart</code>, <code>evap</code>, <code>500miles</code>, <code>individual</code>, <code>obd</code>, <code>csers</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell bildet statische Verträge ab, bestimmt jedoch folgende Laufzeitinteraktionen zwischen Applikation (<code>SW-C</code>), RTE und BSW-Modulen:</p>\n<ol class=\"fig-list\">\n<li><strong>Ereignis- & Fehlermeldung (<code>DiagnosticEventNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die SW-C setzt Diagnosestati asynchron via RTE über die Schnittstelle <code>DiagnosticMonitor</code> (<code>SetEventStatus</code>).</li>\n<li>Das <code>Dem</code> verarbeitet Entprellung und Statusbits (z. B. <code>TEST_FAILED</code>). Ist <code>dtcKind == emissionRelatedDtc</code>, werden MIL-Zähler, Freeze-Frame-Speicherung (Mode $02) und Fault-Memory-Abläufe forciert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Funktionsinhibition (<code>FunctionInhibitionNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schlägt ein Event fehl, aktiviert der <code>Dem</code> den hinterlegten Inhibitionszustand im <code>FiM</code>.</li>\n<li>Betroffene Komponenten prüfen vor Ausführung funktionsrelevanter Routinen über RTE (<code>FunctionInhibition</code>-Port) synchron via <code>GetFunctionPermission(FID, &amp;Permission)</code> die Freigabe.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>IUMPR-Berechnung (<code>ObdRatioServiceNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Modus <code>observer</code>:</strong> Das <code>Dem</code> detektiert Betriebsbedingungen selbstständig. Sobald die durch <code>usedFid</code> referenzierten FIDs fehlerfrei sind, wird der Denominator inkrementiert; schließt der Monitor über <code>DiagnosticEventNeeds</code> erfolgreich ab, wird der Numerator inkrementiert.</li>\n<li><strong>Modus <code>apiUse</code>:</strong> Die SW-C steuert Denominator- und Numerator-Fortschritt explizit durch Aufruf der RTE-APIs (z. B. <code>Dem_RepIUMPRDenLock</code>, <code>Dem_SetIUMPRDenCondition</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>OBD-Dienstabfrage (Services $01, $06, $08, $09):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein externer Tester fordert PIDs/TIDs über CAN/Ethernet an.</li>\n<li><code>Dcm</code> empfängt die Anfrage und ruft synchron oder asynchron die generierten Service-Ports der SW-C auf (z. B. <code>DataServices_OBD_*</code> für PID-Werte oder <code>CallbackDCMRequestControl</code> für Mode $08).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE- & BSW-Konfigurationskonsistenz (TPS_SWCT_1046):</strong></li>\n<li>Deklariert eine SW-C ein <code>ObdRatioServiceNeeds</code>, muss zwingend die Assoziation <code>+rateBasedMonitoredEvent</code> auf ein valides <code>DiagnosticEventNeeds</code> gesetzt sein.</li>\n<li>Fehlt die Zuordnung oder verweist sie auf ein nicht emissionsrelevantes Event (<code>dtcKind != emissionRelatedDtc</code>), verletzen Systemgeneratoren die Konfigurationsvalidierung für OBD-Konformität.</li>\n<li><strong>Vermeidung von Priority Inversion / Deadlocks bei FIDs:</strong></li>\n<li>Die Kopplung von <code>usedFid</code> an <code>ObdRatioServiceNeeds</code> verhindert das unzulässige Inkrementieren des IUMPR-Denominators, wenn vorgelagerte Diagnosen (z. B. Sensor-Plausibilität) die Durchführung des Monitors verhindern. Applikationsentwickler müssen FIDs so modellieren, dass zirkuläre Abhängigkeiten zwischen <code>inhibitingFid</code> und <code>usedFid</code> ausgeschlossen sind.</li>\n<li><strong>Port-Schnittstellenverträge:</strong></li>\n<li>Die Deklaration von <code>ObdPidServiceNeeds</code> bzw. <code>ObdInfoServiceNeeds</code> erzeugt zwingend typisierte Client-Server-Ports an der SW-C. Entwickler müssen sicherstellen, dass die Rückgabe-Payloads exakt der modellierten <code>dataLength</code> entsprechen, um PDU-Pufferüberläufe im <code>Dcm</code> zu verhindern.</li>\n</ul>"}, {"id": "FIG-093a54f2ccad0910", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (M2-Metamodellausschnitt der AUTOSAR Template-Spezifikation <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition diagnostischer Service-Bedarfe (<code>ServiceNeeds</code>) von Software-Komponenten (SW-C) mit Schwerpunkt auf emissionsrelevanter On-Board-Diagnose (OBD-II nach SAE J1979 / ISO 15031, WWH-OBD nach ISO 27145) und Funktionsdeaktivierung (FIM).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient Generatoren (RTE- und BSW-Generatoren) als vertragliche Spezifikationsgrundlage zur automatischen Ableitung von RTE-Service-Ports (Client-Server / Sender-Receiver) sowie BSW-Modulkonfigurationen für <code>Dem</code> (Diagnostic Event Manager), <code>Dcm</code> (Diagnostic Communication Manager) und <code>FiM</code> (Function Inhibition Manager).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basisklassen & Metamodell-Verankerung</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwcServiceDependency</code></strong> (Spezialisierung von <code>ServiceDependency</code>, <code>Identifiable</code>, <code>AtpStructureElement</code>):</li>\n<li>Aggregiert kompositorisch über <code>+serviceNeeds</code> optional eine Instanz (<code>0..1</code>) von <code>ServiceNeeds</code>. Verknüpft die Bedarfe mit konkreten SW-C-Ports oder internem Verhalten.</li>\n<li><strong><code>ServiceNeeds</code></strong> (abstrakt, <code>Identifiable</code>):</li>\n<li>Basisklasse für alle von einer SW-C deklarierten BSW-Dienstbedarfe.</li>\n<li><strong><code>DiagnosticCapabilityElement</code></strong> (abstrakt, erbt von <code>ServiceNeeds</code>):</li>\n<li>Gemeinsame Basis für diagnosebezogene Service-Bedarfe.</li>\n<li><em>Attribute:</em></li>\n<li><code>audience: DiagnosticAudienceEnum [0..*]</code> – Zielgruppe/Freigabekreis (z. B. Aftersales, Manufacturing).</li>\n<li><code>diagRequirement: DiagRequirementIdString [0..1]</code> – Rückverfolgbarkeits-ID zu gesetzlichen/funktionalen Anforderungen.</li>\n<li><code>securityAccessLevel: PositiveInteger [0..1]</code> – Erforderliche Sicherheitsstufe (Seed & Key gemäß UDS/OBD).</li>\n</ul>\n<p class=\"fig-p\">#### Diagnostische Ereignisse & Funktionsinhibition</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticEventNeeds</code></strong> (erbt von <code>DiagnosticCapabilityElement</code>):</li>\n<li>Deklariert ein Diagnoseereignis (Debouncing, DTC-Statusverarbeitung im <code>Dem</code>).</li>\n<li><em>Attribute:</em></li>\n<li><code>prestoredFreezeframeStoredInNvm: Boolean [0..1]</code> – Speicherung vorab erfasster Freeze-Frames im NVM.</li>\n<li><code>usesMonitorData: Boolean [0..1]</code> – Nutzung zusätzlicher Monitordaten.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+deferringFid</code> (<code>0..*</code>) zu <code>FunctionInhibitionNeeds</code>: FIDs zur Verzögerung der Fehlerreaktion/Fehlerspeicherung.</li>\n<li><strong><code>FunctionInhibitionNeeds</code></strong> (erbt direkt von <code>ServiceNeeds</code>):</li>\n<li>Repräsentiert die logische Entkopplung von Fehlererkennung und Fehlerreaktion über Function Identifiers (FIDs) im <code>FiM</code>.</li>\n</ul>\n<p class=\"fig-p\">#### OBD-spezifische Service-Bedarfe (Spezialisierungen von <code>DiagnosticCapabilityElement</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ObdRatioServiceNeeds</code></strong>:</li>\n<li>Konfiguriert das In-Use Monitor Performance Ratio (IUMPR) Tracking gemäß CARB/EPA-Gesetzgebung.</li>\n<li><em>Attribute:</em></li>\n<li><code>connectionType: ObdRatioConnectionKindEnum [0..1]</code> – Steuerungsart (<code>apiUse</code> vs. <code>observer</code>).</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+rateBasedMonitoredEvent</code> (<code>0..1</code>): Referenziert optional ein übergeordnetes <code>DiagnosticEventNeeds</code>.</li>\n<li><code>+usedFid</code> (<code>0..1</code>): Referenziert <code>FunctionInhibitionNeeds</code>, deren Status für das Ratio relevant ist.</li>\n<li><strong><code>ObdRatioDenominatorNeeds</code></strong>:</li>\n<li>Definiert spezifische Nennerbedingungen für IUMPR.</li>\n<li><em>Attribute:</em></li>\n<li><code>denominatorCondition: DiagnosticDenominatorConditionEnum [0..1]</code> – Spezifische Bedingung zur Inkrementierung des Nenners.</li>\n<li><strong><code>ObdPidServiceNeeds</code></strong>:</li>\n<li>Deklariert Bedarfe für Parameter Identifier (PID) Services nach OBD-II ohne eigene Attributspezifikation im Diagramm.</li>\n<li><strong><code>ObdInfoServiceNeeds</code></strong>:</li>\n<li>Spezifiziert Bedarfe bezüglich InfoType-Diensten (OBD Service $09) ohne eigene Attributspezifikation im Diagramm.</li>\n<li><strong><code>ObdControlServiceNeeds</code></strong>:</li>\n<li>Definiert Steuerungsanforderungen für Test-IDs im Rahmen von OBD ohne eigene Attributspezifikation im Diagramm.</li>\n<li><strong><code>ObdMonitorServiceNeeds</code></strong>:</li>\n<li>Beschreibt Service-Bedarfe für On-Board-Monitore (OBD Service $06).</li>\n<li><em>Attribute:</em></li>\n<li><code>unitAndScalingId: PositiveInteger [0..1]</code> – Skalierungs- und Einheitenbezeichner (UASID).</li>\n<li><code>updateKind: DiagnosticMonitorUpdateKindEnum [0..1]</code> – Aktualisierungsmodus der Monitorwerte.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+eventNeeds</code> (<code>0..1</code>): Referenziert das zugehörige <code>DiagnosticEventNeeds</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Aufzählungstypen (Enumerations)</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticDenominatorConditionEnum</code></strong>: Nennerbedingungen (<code>coldstart</code>, <code>evap</code>, <code>500miles</code>, <code>individual</code>, <code>obd</code>, <code>csers</code>, <code>evappurgeflow</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell bildet statische Verträge ab, bestimmt jedoch folgende Laufzeitinteraktionen zwischen Applikation (<code>SW-C</code>), RTE und BSW-Modulen:</p>\n<ol class=\"fig-list\">\n<li><strong>Ereignis- & Fehlermeldung (<code>DiagnosticEventNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die SW-C setzt Diagnosestati asynchron via RTE über die Schnittstelle <code>DiagnosticMonitor</code> (<code>SetEventStatus</code>).</li>\n<li>Das <code>Dem</code> verarbeitet Entprellung und Statusbits (z. B. <code>TEST_FAILED</code>). Ist <code>dtcKind == emissionRelatedDtc</code>, werden MIL-Zähler, Freeze-Frame-Speicherung (Mode $02) und Fault-Memory-Abläufe forciert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Funktionsinhibition (<code>FunctionInhibitionNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schlägt ein Event fehl, aktiviert der <code>Dem</code> den hinterlegten Inhibitionszustand im <code>FiM</code>.</li>\n<li>Betroffene Komponenten prüfen vor Ausführung funktionsrelevanter Routinen über RTE (<code>FunctionInhibition</code>-Port) synchron via <code>GetFunctionPermission(FID, &amp;Permission)</code> die Freigabe.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>IUMPR-Berechnung (<code>ObdRatioServiceNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Modus <code>observer</code>:</strong> Das <code>Dem</code> detektiert Betriebsbedingungen selbstständig. Sobald die durch <code>usedFid</code> referenzierten FIDs fehlerfrei sind, wird der Denominator inkrementiert; schließt der Monitor über <code>DiagnosticEventNeeds</code> erfolgreich ab, wird der Numerator inkrementiert.</li>\n<li><strong>Modus <code>apiUse</code>:</strong> Die SW-C steuert Denominator- und Numerator-Fortschritt explizit durch Aufruf der RTE-APIs (z. B. <code>Dem_RepIUMPRDenLock</code>, <code>Dem_SetIUMPRDenCondition</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>OBD-Dienstabfrage (Services $01, $06, $08, $09):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein externer Tester fordert PIDs/TIDs über CAN/Ethernet an.</li>\n<li><code>Dcm</code> empfängt die Anfrage und ruft synchron oder asynchron die generierten Service-Ports der SW-C auf (z. B. <code>DataServices_OBD_*</code> für PID-Werte oder <code>CallbackDCMRequestControl</code> für Mode $08).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE- & BSW-Konfigurationskonsistenz (TPS_SWCT_1046):</strong></li>\n<li>Deklariert eine SW-C ein <code>ObdRatioServiceNeeds</code>, muss zwingend die Assoziation <code>+rateBasedMonitoredEvent</code> auf ein valides <code>DiagnosticEventNeeds</code> gesetzt sein.</li>\n<li>Fehlt die Zuordnung oder verweist sie auf ein nicht emissionsrelevantes Event (<code>dtcKind != emissionRelatedDtc</code>), verletzen Systemgeneratoren die Konfigurationsvalidierung für OBD-Konformität.</li>\n<li><strong>Vermeidung von Priority Inversion / Deadlocks bei FIDs:</strong></li>\n<li>Die Kopplung von <code>usedFid</code> an <code>ObdRatioServiceNeeds</code> verhindert das unzulässige Inkrementieren des IUMPR-Denominators, wenn vorgelagerte Diagnosen (z. B. Sensor-Plausibilität) die Durchführung des Monitors verhindern. Applikationsentwickler müssen FIDs so modellieren, dass zirkuläre Abhängigkeiten zwischen <code>inhibitingFid</code> und <code>usedFid</code> ausgeschlossen sind.</li>\n<li><strong>Port-Schnittstellenverträge:</strong></li>\n<li>Die Deklaration von <code>ObdPidServiceNeeds</code> bzw. <code>ObdInfoServiceNeeds</code> erzeugt zwingend typisierte Client-Server-Ports an der SW-C. Entwickler müssen sicherstellen, dass die Rückgabe-Payloads exakt der modellierten <code>dataLength</code> entsprechen, um PDU-Pufferüberläufe im <code>Dcm</code> zu verhindern.</li>\n</ul>"}, {"id": "FIG-41de0daf5a6a3483", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (M2-Metamodellausschnitt der AUTOSAR Template-Spezifikation <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition diagnostischer Service-Bedarfe (<code>ServiceNeeds</code>) von Software-Komponenten (SW-C) mit Schwerpunkt auf emissionsrelevanter On-Board-Diagnose (OBD-II nach SAE J1979 / ISO 15031, WWH-OBD nach ISO 27145) und Funktionsdeaktivierung (FIM).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient Generatoren (RTE- und BSW-Generatoren) als vertragliche Spezifikationsgrundlage zur automatischen Ableitung von RTE-Service-Ports (Client-Server / Sender-Receiver) sowie BSW-Modulkonfigurationen für <code>Dem</code> (Diagnostic Event Manager), <code>Dcm</code> (Diagnostic Communication Manager) und <code>FiM</code> (Function Inhibition Manager).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basisklassen & Metamodell-Verankerung</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwcServiceDependency</code></strong> (Spezialisierung von <code>ServiceDependency</code>, <code>Identifiable</code>, <code>AtpStructureElement</code>):</li>\n<li>Aggregiert kompositorisch über <code>+serviceNeeds</code> optional eine Instanz (<code>0..1</code>) von <code>ServiceNeeds</code>. Verknüpft die Bedarfe mit konkreten SW-C-Ports oder internem Verhalten.</li>\n<li><strong><code>ServiceNeeds</code></strong> (abstrakt, <code>Identifiable</code>):</li>\n<li>Basisklasse für alle von einer SW-C deklarierten BSW-Dienstbedarfe.</li>\n<li><strong><code>DiagnosticCapabilityElement</code></strong> (abstrakt, erbt von <code>ServiceNeeds</code>):</li>\n<li>Gemeinsame Basis für diagnosebezogene Service-Bedarfe.</li>\n<li><em>Attribute:</em></li>\n<li><code>audience: DiagnosticAudienceEnum [0..*]</code> – Zielgruppe/Freigabekreis (z. B. Aftersales, Manufacturing).</li>\n<li><code>diagRequirement: DiagRequirementIdString [0..1]</code> – Rückverfolgbarkeits-ID zu gesetzlichen/funktionalen Anforderungen.</li>\n<li><code>securityAccessLevel: PositiveInteger [0..1]</code> – Erforderliche Sicherheitsstufe (Seed & Key gemäß UDS/OBD).</li>\n</ul>\n<p class=\"fig-p\">#### Diagnostische Ereignisse & Funktionsinhibition</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticEventNeeds</code></strong> (erbt von <code>DiagnosticCapabilityElement</code>):</li>\n<li>Deklariert ein Diagnoseereignis (Debouncing, DTC-Statusverarbeitung im <code>Dem</code>).</li>\n<li><em>Attribute:</em></li>\n<li><code>prestoredFreezeframeStoredInNvm: Boolean [0..1]</code> – Speicherung vorab erfasster Freeze-Frames im NVM.</li>\n<li><code>usesMonitorData: Boolean [0..1]</code> – Nutzung zusätzlicher Monitordaten.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+deferringFid</code> (<code>0..*</code>) zu <code>FunctionInhibitionNeeds</code>: FIDs zur Verzögerung der Fehlerreaktion/Fehlerspeicherung.</li>\n<li><strong><code>FunctionInhibitionNeeds</code></strong> (erbt direkt von <code>ServiceNeeds</code>):</li>\n<li>Repräsentiert die logische Entkopplung von Fehlererkennung und Fehlerreaktion über Function Identifiers (FIDs) im <code>FiM</code>.</li>\n</ul>\n<p class=\"fig-p\">#### OBD-spezifische Service-Bedarfe (Spezialisierungen von <code>DiagnosticCapabilityElement</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ObdRatioServiceNeeds</code></strong>:</li>\n<li>Konfiguriert das In-Use Monitor Performance Ratio (IUMPR) Tracking gemäß CARB/EPA-Gesetzgebung.</li>\n<li><em>Attribute:</em></li>\n<li><code>connectionType: ObdRatioConnectionKindEnum [0..1]</code> – Steuerungsart (<code>apiUse</code> vs. <code>observer</code>).</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+rateBasedMonitoredEvent</code> (<code>0..1</code>): Referenziert optional ein übergeordnetes <code>DiagnosticEventNeeds</code>.</li>\n<li><code>+usedFid</code> (<code>0..1</code>): Referenziert <code>FunctionInhibitionNeeds</code>, deren Status für das Ratio relevant ist.</li>\n<li><strong><code>ObdRatioDenominatorNeeds</code></strong>:</li>\n<li>Definiert spezifische Nennerbedingungen für IUMPR.</li>\n<li><em>Attribute:</em></li>\n<li><code>denominatorCondition: DiagnosticDenominatorConditionEnum [0..1]</code> – Spezifische Bedingung zur Inkrementierung des Nenners.</li>\n<li><strong><code>ObdPidServiceNeeds</code></strong>:</li>\n<li>Deklariert Bedarfe für Parameter Identifier (PID) Services nach OBD-II ohne eigene Attributspezifikation im Diagramm.</li>\n<li><strong><code>ObdInfoServiceNeeds</code></strong>:</li>\n<li>Spezifiziert Bedarfe bezüglich InfoType-Diensten (OBD Service $09) ohne eigene Attributspezifikation im Diagramm.</li>\n<li><strong><code>ObdControlServiceNeeds</code></strong>:</li>\n<li>Definiert Steuerungsanforderungen für Test-IDs im Rahmen von OBD ohne eigene Attributspezifikation im Diagramm.</li>\n<li><strong><code>ObdMonitorServiceNeeds</code></strong>:</li>\n<li>Beschreibt Service-Bedarfe für On-Board-Monitore (OBD Service $06).</li>\n<li><em>Attribute:</em></li>\n<li><code>unitAndScalingId: PositiveInteger [0..1]</code> – Skalierungs- und Einheitenbezeichner (UASID).</li>\n<li><code>updateKind: DiagnosticMonitorUpdateKindEnum [0..1]</code> – Aktualisierungsmodus der Monitorwerte.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+eventNeeds</code> (<code>0..1</code>): Referenziert das zugehörige <code>DiagnosticEventNeeds</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Aufzählungstypen (Enumerations)</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticDenominatorConditionEnum</code></strong>: Nennerbedingungen (<code>coldstart</code>, <code>evap</code>, <code>500miles</code>, <code>individual</code>, <code>obd</code>, <code>csers</code>, <code>evappurgeflow</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell bildet statische Verträge ab, bestimmt jedoch folgende Laufzeitinteraktionen zwischen Applikation (<code>SW-C</code>), RTE und BSW-Modulen:</p>\n<ol class=\"fig-list\">\n<li><strong>Ereignis- & Fehlermeldung (<code>DiagnosticEventNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die SW-C setzt Diagnosestati asynchron via RTE über die Schnittstelle <code>DiagnosticMonitor</code> (<code>SetEventStatus</code>).</li>\n<li>Das <code>Dem</code> verarbeitet Entprellung und Statusbits (z. B. <code>TEST_FAILED</code>). Ist <code>dtcKind == emissionRelatedDtc</code>, werden MIL-Zähler, Freeze-Frame-Speicherung (Mode $02) und Fault-Memory-Abläufe forciert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Funktionsinhibition (<code>FunctionInhibitionNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schlägt ein Event fehl, aktiviert der <code>Dem</code> den hinterlegten Inhibitionszustand im <code>FiM</code>.</li>\n<li>Betroffene Komponenten prüfen vor Ausführung funktionsrelevanter Routinen über RTE (<code>FunctionInhibition</code>-Port) synchron via <code>GetFunctionPermission(FID, &amp;Permission)</code> die Freigabe.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>IUMPR-Berechnung (<code>ObdRatioServiceNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Modus <code>observer</code>:</strong> Das <code>Dem</code> detektiert Betriebsbedingungen selbstständig. Sobald die durch <code>usedFid</code> referenzierten FIDs fehlerfrei sind, wird der Denominator inkrementiert; schließt der Monitor über <code>DiagnosticEventNeeds</code> erfolgreich ab, wird der Numerator inkrementiert.</li>\n<li><strong>Modus <code>apiUse</code>:</strong> Die SW-C steuert Denominator- und Numerator-Fortschritt explizit durch Aufruf der RTE-APIs (z. B. <code>Dem_RepIUMPRDenLock</code>, <code>Dem_SetIUMPRDenCondition</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>OBD-Dienstabfrage (Services $01, $06, $08, $09):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein externer Tester fordert PIDs/TIDs über CAN/Ethernet an.</li>\n<li><code>Dcm</code> empfängt die Anfrage und ruft synchron oder asynchron die generierten Service-Ports der SW-C auf (z. B. <code>DataServices_OBD_*</code> für PID-Werte oder <code>CallbackDCMRequestControl</code> für Mode $08).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE- & BSW-Konfigurationskonsistenz (TPS_SWCT_1046):</strong></li>\n<li>Deklariert eine SW-C ein <code>ObdRatioServiceNeeds</code>, muss zwingend die Assoziation <code>+rateBasedMonitoredEvent</code> auf ein valides <code>DiagnosticEventNeeds</code> gesetzt sein.</li>\n<li>Fehlt die Zuordnung oder verweist sie auf ein nicht emissionsrelevantes Event (<code>dtcKind != emissionRelatedDtc</code>), verletzen Systemgeneratoren die Konfigurationsvalidierung für OBD-Konformität.</li>\n<li><strong>Vermeidung von Priority Inversion / Deadlocks bei FIDs:</strong></li>\n<li>Die Kopplung von <code>usedFid</code> an <code>ObdRatioServiceNeeds</code> verhindert das unzulässige Inkrementieren des IUMPR-Denominators, wenn vorgelagerte Diagnosen (z. B. Sensor-Plausibilität) die Durchführung des Monitors verhindern. Applikationsentwickler müssen FIDs so modellieren, dass zirkuläre Abhängigkeiten zwischen <code>inhibitingFid</code> und <code>usedFid</code> ausgeschlossen sind.</li>\n<li><strong>Port-Schnittstellenverträge:</strong></li>\n<li>Die Deklaration von <code>ObdPidServiceNeeds</code> bzw. <code>ObdInfoServiceNeeds</code> erzeugt zwingend typisierte Client-Server-Ports an der SW-C. Entwickler müssen sicherstellen, dass die Rückgabe-Payloads exakt der modellierten <code>dataLength</code> entsprechen, um PDU-Pufferüberläufe im <code>Dcm</code> zu verhindern.</li>\n</ul>"}, {"id": "FIG-e3244d72cfee7381", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (M2-Metamodellausschnitt der AUTOSAR Template-Spezifikation <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition diagnostischer Service-Bedarfe (<code>ServiceNeeds</code>) von Software-Komponenten (SW-C) mit Schwerpunkt auf emissionsrelevanter On-Board-Diagnose (OBD-II nach SAE J1979 / ISO 15031, WWH-OBD nach ISO 27145) und Funktionsdeaktivierung (FIM).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient Generatoren (RTE- und BSW-Generatoren) als vertragliche Spezifikationsgrundlage zur automatischen Ableitung von RTE-Service-Ports (Client-Server / Sender-Receiver) sowie BSW-Modulkonfigurationen für <code>Dem</code> (Diagnostic Event Manager), <code>Dcm</code> (Diagnostic Communication Manager) und <code>FiM</code> (Function Inhibition Manager).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Basisklassen & Metamodell-Verankerung</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwcServiceDependency</code></strong> (Spezialisierung von <code>ServiceDependency</code>, <code>Identifiable</code>, <code>AtpStructureElement</code>):</li>\n<li>Aggregiert kompositorisch über <code>+serviceNeeds</code> optional eine Instanz (<code>0..1</code>) von <code>ServiceNeeds</code>. Verknüpft die Bedarfe mit konkreten SW-C-Ports oder internem Verhalten.</li>\n<li><strong><code>ServiceNeeds</code></strong> (abstrakt, <code>Identifiable</code>):</li>\n<li>Basisklasse für alle von einer SW-C deklarierten BSW-Dienstbedarfe.</li>\n<li><strong><code>DiagnosticCapabilityElement</code></strong> (abstrakt, erbt von <code>ServiceNeeds</code>):</li>\n<li>Gemeinsame Basis für diagnosebezogene Service-Bedarfe.</li>\n<li><em>Attribute:</em></li>\n<li><code>audience: DiagnosticAudienceEnum [0..*]</code> – Zielgruppe/Freigabekreis (z. B. Aftersales, Manufacturing).</li>\n<li><code>diagRequirement: DiagRequirementIdString [0..1]</code> – Rückverfolgbarkeits-ID zu gesetzlichen/funktionalen Anforderungen.</li>\n<li><code>securityAccessLevel: PositiveInteger [0..1]</code> – Erforderliche Sicherheitsstufe (Seed & Key gemäß UDS/OBD).</li>\n</ul>\n<p class=\"fig-p\">#### Diagnostische Ereignisse & Funktionsinhibition</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticEventNeeds</code></strong> (erbt von <code>DiagnosticCapabilityElement</code>):</li>\n<li>Deklariert ein Diagnoseereignis (Debouncing, DTC-Statusverarbeitung im <code>Dem</code>).</li>\n<li><em>Attribute:</em></li>\n<li><code>prestoredFreezeframeStoredInNvm: Boolean [0..1]</code> – Speicherung vorab erfasster Freeze-Frames im NVM.</li>\n<li><code>usesMonitorData: Boolean [0..1]</code> – Nutzung zusätzlicher Monitordaten.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+deferringFid</code> (<code>0..*</code>) zu <code>FunctionInhibitionNeeds</code>: FIDs zur Verzögerung der Fehlerreaktion/Fehlerspeicherung.</li>\n<li><strong><code>FunctionInhibitionNeeds</code></strong> (erbt direkt von <code>ServiceNeeds</code>):</li>\n<li>Repräsentiert die logische Entkopplung von Fehlererkennung und Fehlerreaktion über Function Identifiers (FIDs) im <code>FiM</code>.</li>\n</ul>\n<p class=\"fig-p\">#### OBD-spezifische Service-Bedarfe (Spezialisierungen von <code>DiagnosticCapabilityElement</code>)</p>\n<ul class=\"fig-list\">\n<li><strong><code>ObdRatioServiceNeeds</code></strong>:</li>\n<li>Konfiguriert das In-Use Monitor Performance Ratio (IUMPR) Tracking gemäß CARB/EPA-Gesetzgebung.</li>\n<li><em>Attribute:</em></li>\n<li><code>connectionType: ObdRatioConnectionKindEnum [0..1]</code> – Steuerungsart (<code>apiUse</code> vs. <code>observer</code>).</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+rateBasedMonitoredEvent</code> (<code>0..1</code>): Referenziert optional ein übergeordnetes <code>DiagnosticEventNeeds</code>.</li>\n<li><code>+usedFid</code> (<code>0..1</code>): Referenziert <code>FunctionInhibitionNeeds</code>, deren Status für das Ratio relevant ist.</li>\n<li><strong><code>ObdRatioDenominatorNeeds</code></strong>:</li>\n<li>Definiert spezifische Nennerbedingungen für IUMPR.</li>\n<li><em>Attribute:</em></li>\n<li><code>denominatorCondition: DiagnosticDenominatorConditionEnum [0..1]</code> – Spezifische Bedingung zur Inkrementierung des Nenners.</li>\n<li><strong><code>ObdPidServiceNeeds</code></strong>:</li>\n<li>Deklariert Bedarfe für Parameter Identifier (PID) Services nach OBD-II ohne eigene Attributspezifikation im Diagramm.</li>\n<li><strong><code>ObdInfoServiceNeeds</code></strong>:</li>\n<li>Spezifiziert Bedarfe bezüglich InfoType-Diensten (OBD Service $09) ohne eigene Attributspezifikation im Diagramm.</li>\n<li><strong><code>ObdControlServiceNeeds</code></strong>:</li>\n<li>Definiert Steuerungsanforderungen für Test-IDs im Rahmen von OBD ohne eigene Attributspezifikation im Diagramm.</li>\n<li><strong><code>ObdMonitorServiceNeeds</code></strong>:</li>\n<li>Beschreibt Service-Bedarfe für On-Board-Monitore (OBD Service $06).</li>\n<li><em>Attribute:</em></li>\n<li><code>unitAndScalingId: PositiveInteger [0..1]</code> – Skalierungs- und Einheitenbezeichner (UASID).</li>\n<li><code>updateKind: DiagnosticMonitorUpdateKindEnum [0..1]</code> – Aktualisierungsmodus der Monitorwerte.</li>\n<li><em>Assoziationen:</em></li>\n<li><code>+eventNeeds</code> (<code>0..1</code>): Referenziert das zugehörige <code>DiagnosticEventNeeds</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Aufzählungstypen (Enumerations)</p>\n<ul class=\"fig-list\">\n<li><strong><code>DiagnosticDenominatorConditionEnum</code></strong>: Nennerbedingungen (<code>coldstart</code>, <code>evap</code>, <code>500miles</code>, <code>individual</code>, <code>obd</code>, <code>csers</code>, <code>evappurgeflow</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell bildet statische Verträge ab, bestimmt jedoch folgende Laufzeitinteraktionen zwischen Applikation (<code>SW-C</code>), RTE und BSW-Modulen:</p>\n<ol class=\"fig-list\">\n<li><strong>Ereignis- & Fehlermeldung (<code>DiagnosticEventNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die SW-C setzt Diagnosestati asynchron via RTE über die Schnittstelle <code>DiagnosticMonitor</code> (<code>SetEventStatus</code>).</li>\n<li>Das <code>Dem</code> verarbeitet Entprellung und Statusbits (z. B. <code>TEST_FAILED</code>). Ist <code>dtcKind == emissionRelatedDtc</code>, werden MIL-Zähler, Freeze-Frame-Speicherung (Mode $02) und Fault-Memory-Abläufe forciert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Funktionsinhibition (<code>FunctionInhibitionNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schlägt ein Event fehl, aktiviert der <code>Dem</code> den hinterlegten Inhibitionszustand im <code>FiM</code>.</li>\n<li>Betroffene Komponenten prüfen vor Ausführung funktionsrelevanter Routinen über RTE (<code>FunctionInhibition</code>-Port) synchron via <code>GetFunctionPermission(FID, &amp;Permission)</code> die Freigabe.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>IUMPR-Berechnung (<code>ObdRatioServiceNeeds</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Modus <code>observer</code>:</strong> Das <code>Dem</code> detektiert Betriebsbedingungen selbstständig. Sobald die durch <code>usedFid</code> referenzierten FIDs fehlerfrei sind, wird der Denominator inkrementiert; schließt der Monitor über <code>DiagnosticEventNeeds</code> erfolgreich ab, wird der Numerator inkrementiert.</li>\n<li><strong>Modus <code>apiUse</code>:</strong> Die SW-C steuert Denominator- und Numerator-Fortschritt explizit durch Aufruf der RTE-APIs (z. B. <code>Dem_RepIUMPRDenLock</code>, <code>Dem_SetIUMPRDenCondition</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>OBD-Dienstabfrage (Services $01, $06, $08, $09):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ein externer Tester fordert PIDs/TIDs über CAN/Ethernet an.</li>\n<li><code>Dcm</code> empfängt die Anfrage und ruft synchron oder asynchron die generierten Service-Ports der SW-C auf (z. B. <code>DataServices_OBD_*</code> für PID-Werte oder <code>CallbackDCMRequestControl</code> für Mode $08).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE- & BSW-Konfigurationskonsistenz (TPS_SWCT_1046):</strong></li>\n<li>Deklariert eine SW-C ein <code>ObdRatioServiceNeeds</code>, muss zwingend die Assoziation <code>+rateBasedMonitoredEvent</code> auf ein valides <code>DiagnosticEventNeeds</code> gesetzt sein.</li>\n<li>Fehlt die Zuordnung oder verweist sie auf ein nicht emissionsrelevantes Event (<code>dtcKind != emissionRelatedDtc</code>), verletzen Systemgeneratoren die Konfigurationsvalidierung für OBD-Konformität.</li>\n<li><strong>Vermeidung von Priority Inversion / Deadlocks bei FIDs:</strong></li>\n<li>Die Kopplung von <code>usedFid</code> an <code>ObdRatioServiceNeeds</code> verhindert das unzulässige Inkrementieren des IUMPR-Denominators, wenn vorgelagerte Diagnosen (z. B. Sensor-Plausibilität) die Durchführung des Monitors verhindern. Applikationsentwickler müssen FIDs so modellieren, dass zirkuläre Abhängigkeiten zwischen <code>inhibitingFid</code> und <code>usedFid</code> ausgeschlossen sind.</li>\n<li><strong>Port-Schnittstellenverträge:</strong></li>\n<li>Die Deklaration von <code>ObdPidServiceNeeds</code> bzw. <code>ObdInfoServiceNeeds</code> erzeugt zwingend typisierte Client-Server-Ports an der SW-C. Entwickler müssen sicherstellen, dass die Rückgabe-Payloads exakt der modellierten <code>dataLength</code> entsprechen, um PDU-Pufferüberläufe im <code>Dcm</code> zu verhindern.</li>\n</ul>"}], "trans": [{"from": "FIG-6d4455723fadd3b4", "to": "FIG-7b99c529e35c0d0d", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>SwcServiceDependency</code>: Namensraum-Präfix <code>ServiceMapping::</code> im Klassennamen entfernt.</li>\n<li><code>DiagnosticEventNeeds</code>: Kardinalität von <code>considerPtoStatus</code> von <code>[1]</code> auf <code>[0..1]</code> geändert.</li>\n<li><code>DiagnosticEventNeeds</code>: Kardinalität von <code>dtcKind</code> von <code>[1]</code> auf <code>[0..1]</code> geändert.</li>\n<li><code>DiagnosticEventNeeds</code>: Attribut <code>obdDtcNumber: PositiveInteger [0..1]</code> hinzugefügt.</li>\n<li><code>DiagnosticEventNeeds</code>: Attribut <code>udsDtcNumber: PositiveInteger [0..1]</code> hinzugefügt.</li>\n</ul>"}, {"from": "FIG-7b99c529e35c0d0d", "to": "FIG-1e7e63823cc98073", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>DiagnosticEventNeeds</code>: Attribut <code>dtcNumber: PositiveInteger [0..1]</code> entfernt.</li>\n<li><code>DiagnosticEventNeeds</code>: Attribut <code>reportBehavior: ReportBehaviorEnum [0..1]</code> hinzugefügt.</li>\n<li><code>DiagnosticEventNeeds</code>: Assoziation <code>+deferringFid</code> mit Kardinalität <code>0..*</code> zu <code>FunctionInhibitionNeeds</code> hinzugefügt.</li>\n<li><code>DiagnosticEventNeeds</code>: Kardinalität <code>0..1</code> an der Assoziation <code>+inhibitingFid</code> zu <code>FunctionInhibitionNeeds</code> explizit beschriftet.</li>\n</ul>"}, {"from": "FIG-1e7e63823cc98073", "to": "FIG-cc9257a44469d4b5", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>ObdPidServiceNeeds</code>: Kardinalität von <code>parameterId</code> und <code>standard</code> jeweils von <code>[1]</code> auf <code>[0..1]</code> geändert.</li>\n<li><code>ObdRatioServiceNeeds</code>: Kardinalität von <code>iumprGroup</code> von <code>[1]</code> auf <code>[0..1]</code> geändert.</li>\n<li><code>ObdInfoServiceNeeds</code>: Kardinalität von <code>infoType</code> von <code>[1]</code> auf <code>[0..1]</code> geändert.</li>\n<li><code>ObdMonitorServiceNeeds</code>: Kardinalität von <code>onBoardMonitorId</code>, <code>testId</code> und <code>unitAndScalingId</code> jeweils von <code>[1]</code> auf <code>[0..1]</code> geändert.</li>\n<li><code>ObdControlServiceNeeds</code>: Kardinalität von <code>testId</code> von <code>[1]</code> auf <code>[0..1]</code> geändert.</li>\n</ul>"}, {"from": "FIG-cc9257a44469d4b5", "to": "FIG-853b357428bde6bc", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>DiagnosticEventNeeds</code>: Attribute <code>prestoredFreezeframeStoredInNvm: Boolean [0..1]</code> und <code>usesMonitorData: Boolean [0..1]</code> hinzugefügt.</li>\n<li><code>ObdMonitorServiceNeeds</code>: Attribut <code>updateKind: DiagnosticMonitorUpdateKindEnum [0..1]</code> hinzugefügt.</li>\n<li><code>ObdMonitorServiceNeeds</code>: Assoziation <code>+eventNeeds</code> mit Kardinalität <code>0..1</code> zu <code>DiagnosticEventNeeds</code> hinzugefügt.</li>\n<li><code>ObdRatioServiceNeeds</code>: Attribut <code>denominatorGroup: DiagnosticDenominatorConditionEnum [0..1]</code> hinzugefügt.</li>\n<li><code>ObdRatioDenominatorNeeds</code>: Neue Spezialisierung von <code>DiagnosticCapabilityElement</code> mit Attribut <code>denominatorCondition: DiagnosticDenominatorConditionEnum [0..1]</code> hinzugefügt.</li>\n<li><code>DiagnosticDenominatorConditionEnum</code>: Neues Enumerationselement mit den Literalen <code>coldstart</code>, <code>evap</code>, <code>500miles</code>, <code>individual</code> und <code>obd</code> hinzugefügt.</li>\n<li><code>DiagnosticMonitorUpdateKindEnum</code>: Neues Enumerationselement mit den Literalen <code>always</code> und <code>steady</code> hinzugefügt.</li>\n</ul>"}, {"from": "FIG-853b357428bde6bc", "to": "FIG-921a2c30bcb6373b", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-921a2c30bcb6373b", "to": "FIG-f0baf71606385c89", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>SwcServiceDependency</code>: Kardinalität der Komposition <code>+serviceNeeds</code> zu <code>ServiceNeeds</code> von <code>1</code> auf <code>0..1</code> geändert.</li>\n<li><code>DiagnosticEventNeeds</code>: Assoziationen <code>+inhibitingFid</code> (<code>0..1</code>) und <code>+inhibitingSecondaryFid</code> (<code>0..*</code>) zu <code>FunctionInhibitionNeeds</code> entfernt.</li>\n<li><code>ObdRatioServiceNeeds</code>: Kardinalität von <code>connectionType</code> von <code>[1]</code> auf <code>[0..1]</code> geändert.</li>\n<li><code>ObdRatioServiceNeeds</code>: Kardinalität der Assoziation <code>+rateBasedMonitoredEvent</code> zu <code>DiagnosticEventNeeds</code> von <code>1</code> auf <code>0..1</code> geändert.</li>\n<li><code>ObdRatioServiceNeeds</code>: Assoziation <code>+usedSecondaryFid</code> (<code>0..*</code>) zu <code>FunctionInhibitionNeeds</code> entfernt.</li>\n<li>Enumerationen <code>DiagnosticDenominatorConditionEnum</code> und <code>DiagnosticMonitorUpdateKindEnum</code>: Im Layout von unterhalb des Diagramms nach rechts neben die ServiceNeeds-Klassen verschoben.</li>\n</ul>"}, {"from": "FIG-f0baf71606385c89", "to": "FIG-411a6b54ec9c4afc", "fr": "R20-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>DiagnosticEventNeeds</code>: Entfall der Attribute <code>considerPtoStatus</code>, <code>dtcKind</code>, <code>obdDtcNumber</code>, <code>reportBehavior</code> und <code>udsDtcNumber</code> (nur <code>prestoredFreezeframeStoredInNvm</code> und <code>usesMonitorData</code> verbleiben).</li>\n<li><code>ObdMonitorServiceNeeds</code>: Entfall der Attribute <code>onBoardMonitorId</code>, <code>testId</code> und <code>updateKind</code> (nur <code>unitAndScalingId</code> verbleibt).</li>\n<li><code>ObdRatioServiceNeeds</code>: Entfall der Attribute <code>denominatorGroup</code> und <code>iumprGroup</code> (nur <code>connectionType</code> verbleibt).</li>\n<li><code>ObdPidServiceNeeds</code>: Entfall aller Attribute (<code>dataLength</code>, <code>parameterId</code>, <code>standard</code>).</li>\n<li><code>ObdInfoServiceNeeds</code>: Entfall aller Attribute (<code>dataLength</code>, <code>infoType</code>).</li>\n<li><code>ObdControlServiceNeeds</code>: Entfall des Attributs <code>testId</code>.</li>\n<li><code>DiagnosticDenominatorConditionEnum</code>: Ergänzung des Literals <code>csers</code>.</li>\n<li>Entfall der eigenständigen Aufzählungstypen <code>DtcKindEnum</code>, <code>ObdRatioConnectionKindEnum</code> und <code>DiagnosticMonitorUpdateKindEnum</code> aus der Diagrammdarstellung.</li>\n<li>Umordnung des Diagrammlayouts mit Platzierung von <code>ObdPidServiceNeeds</code>, <code>ObdInfoServiceNeeds</code> und <code>ObdControlServiceNeeds</code> links von <code>DiagnosticCapabilityElement</code>.</li>\n</ul>"}, {"from": "FIG-411a6b54ec9c4afc", "to": "FIG-093a54f2ccad0910", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>ObdMonitorServiceNeeds</code>: Ergänzung des Attributs <code>updateKind: DiagnosticMonitorUpdateKindEnum [0..1]</code>.</li>\n<li><code>DiagnosticDenominatorConditionEnum</code>: Ergänzung des Literals <code>evappurgeflow</code>.</li>\n</ul>"}, {"from": "FIG-093a54f2ccad0910", "to": "FIG-41de0daf5a6a3483", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>DiagnosticDenominatorConditionEnum</code>: Ergänzung der Abschnittsüberschrift <em>literals</em> über den Enumerationswerten (Formatierungsanpassung im Metamodell).</li>\n</ul>"}, {"from": "FIG-41de0daf5a6a3483", "to": "FIG-e3244d72cfee7381", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
